import React from 'react';
import { Navigate } from 'react-router-dom';

interface ProtectedRouteProps {
    children: React.ReactElement;
    allowedRoles: string[]; // e.g., ['Admin', 'Etudiant']
}

const ProtectedRoute: React.FC<ProtectedRouteProps> = ({ children, allowedRoles }) => {
    const userStr = localStorage.getItem('user');

    if (!userStr) {
        return <Navigate to="/connexion" replace />;
    }

    try {
        const user = JSON.parse(userStr);
        // Normalize role check
        // In Airtable we see "Statut" which can be "Admin", "Administrateur", "Etudiant"
        const userRole = user['Statut'];

        const hasPermission = allowedRoles.some(role => {
            if (role === 'Admin') {
                return userRole === 'Admin' || userRole === 'Administrateur';
            }
            if (role === 'Etudiant') {
                return userRole === 'Étudiant' || userRole === 'Etudiant';
            }
            return userRole === role;
        });

        if (!hasPermission) {
            // User is logged in but doesn't have the right role.
            // Redirect to their appropriate home based on their actual role
            if (userRole === 'Admin' || userRole === 'Administrateur') {
                return <Navigate to="/admin" replace />;
            } else {
                return <Navigate to="/mon-espace" replace />;
            }
        }

        return children;
    } catch (e) {
        console.error("Auth Error:", e);
        localStorage.removeItem('user');
        return <Navigate to="/connexion" replace />;
    }
};

export default ProtectedRoute;

import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import HeaderMain from '../components/HeaderMain';
import FooterOther from '../components/FooterOther';
import Oeil from '../components/Oeil';
import { verifyStudent } from '../services/airtable';

function Connexion() {
    const navigate = useNavigate();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState<string | null>(null);
    const [isLoading, setIsLoading] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);
        setIsLoading(true);

        try {
            const result = await verifyStudent(email, password);

            if (result.success) {
                // Store user info in local storage
                console.log('Login successful:', result.student);
                localStorage.setItem('user', JSON.stringify(result.student));

                // Check status for redirection
                const studentData = result.student as any;
                const status = studentData['Statut'];
                if (status === 'Admin' || status === 'Administrateur') {
                    navigate('/admin');
                } else {
                    navigate('/mon-espace');
                }
            } else {
                setError(result.message || "Erreur lors de la connexion");
            }
        } catch (err) {
            setError("Une erreur est survenue. Veuillez réessayer.");
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-accent-50 flex flex-col pt-6">
            <HeaderMain />
            <div className="flex-1 flex items-center justify-center py-12 px-6">
                <div className="bg-white rounded-3xl shadow-xl p-8 md:p-12 max-w-md w-full">
                    {/* Header */}
                    <div className="text-center mb-8">
                        <h1 className="text-3xl font-bold text-gray-900 mb-2">Connexion</h1>
                        <p className="text-gray-600">Connectez-vous à votre espace personnel</p>
                    </div>

                    {/* Form */}
                    <form onSubmit={handleSubmit} className="space-y-6">
                        {error && (
                            <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm font-medium">
                                {error}
                            </div>
                        )}
                        {/* Email Input */}
                        <div>
                            <label htmlFor="email" className="block text-sm font-semibold text-gray-900 mb-2">
                                Email
                            </label>
                            <input
                                type="email"
                                id="email"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                placeholder="example@email.com"
                                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-brand focus:border-transparent bg-gray-50"
                                required
                            />
                        </div>

                        {/* Password Input */}
                        <div>
                            <label htmlFor="password" className="block text-sm font-semibold text-gray-900 mb-2">
                                Mot de passe
                            </label>
                            <input
                                type="password"
                                id="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                placeholder="········"
                                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-brand focus:border-transparent bg-gray-50"
                                required
                            />
                        </div>

                        {/* Forgot Password Link */}
                        <div className="text-left">
                            <Link to="/mot-de-passe-oublie" className="text-brand hover:text-brand-600 text-sm font-medium">
                                Mot de passe oublié ?
                            </Link>
                        </div>

                        {/* Submit Button */}
                        <button
                            type="submit"
                            disabled={isLoading}
                            className={`w-full py-3 bg-brand text-white font-bold rounded-lg hover:bg-brand-600 transition-colors shadow-md ${isLoading ? 'opacity-70 cursor-not-allowed' : ''}`}
                        >
                            {isLoading ? 'Connexion...' : 'Se connecter'}
                        </button>
                    </form>

                    {/* Sign Up Link */}
                    <div className="text-center mt-6">
                        <p className="text-gray-600 text-sm">
                            Pas encore de compte ?{' '}
                            <Link to="/inscription" className="text-brand hover:text-brand-600 font-semibold">
                                S'inscrire
                            </Link>
                        </p>
                    </div>
                </div>

            </div>
            <Oeil />
            <FooterOther />
        </div>
    );
}

export default Connexion;

import React, { useState, useEffect } from 'react';
import { ArrowLeft, Edit, Calendar, Trash2, Plus } from 'lucide-react';
import { Link, useParams } from 'react-router-dom';
import HeaderAdmin from '../components/HeaderAdmin';
import FooterMain from '../components/FooterMain';
import Oeil from '../components/Oeil';
import { getStudent, getTasksForStudent, createTask, updateTaskStatus, Task, getStudentRdvs, StudentRdv, updateRdvSummary } from '../services/airtable';



const DetailEtudiant: React.FC = () => {
    const { id } = useParams();
    const [activeTab, setActiveTab] = useState<'historique' | 'nouveau'>('historique');
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [isNewTaskModalOpen, setIsNewTaskModalOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);

    // Student info
    const [studentInfo, setStudentInfo] = useState({
        fullName: '',
        birthDate: '',
        email: '',
        phone: '',
        address: '',
        university: '',
        filiere: '',
        handicapType: '',
        inscriptionDate: '',
        status: ''
    });

    // Tasks
    const [tasks, setTasks] = useState<Task[]>([]);

    // RDVs
    const [rdvs, setRdvs] = useState<StudentRdv[]>([]);
    const [selectedRdvId, setSelectedRdvId] = useState('');
    const [summaryContent, setSummaryContent] = useState('');
    const [isSubmittingSummary, setIsSubmittingSummary] = useState(false);

    useEffect(() => {
        const fetchData = async () => {
            if (!id) return;
            try {
                const student = await getStudent(id);
                if (student) {
                    setStudentInfo({
                        fullName: `${student.prenom} ${student.nom}`,
                        birthDate: "01/01/2000", // Placeholder or fetch if available
                        email: student.email,
                        phone: student.phone,
                        address: "Adresse non renseignée", // Placeholder
                        university: student.university,
                        filiere: student.fieldOfStudy + " " + student.studyLevel,
                        handicapType: student.disabilityTypes.join(', '),
                        inscriptionDate: "01/09/2023", // Placeholder
                        status: student.statut || ''
                    });
                }
                const fetchedTasks = await getTasksForStudent(id);
                setTasks(fetchedTasks);

                const fetchedRdvs = await getStudentRdvs(id);
                setRdvs(fetchedRdvs);
            } catch (error) {
                console.error("Error loading data", error);
            } finally {
                setIsLoading(false);
            }
        };
        fetchData();
    }, [id]);

    const [newTask, setNewTask] = useState({
        title: '',
        date: ''
    });

    const handleDeleteTask = (taskId: string) => {
        setTasks(tasks.filter(task => task.id !== taskId));
    };

    const handleAddTask = async () => {
        if (newTask.title && newTask.date && id) {
            try {
                await createTask(newTask.title, newTask.date, id);
                // Refresh tasks with a slight delay
                setTimeout(async () => {
                    const fetchedTasks = await getTasksForStudent(id);
                    setTasks(fetchedTasks);
                }, 500);

                setNewTask({ title: '', date: '' });
                setIsNewTaskModalOpen(false);
            } catch (error) {
                console.error("Failed to create task", error);
            }
        }
    };

    // Form logic
    const handleSaveSummary = async () => {
        if (!selectedRdvId || !summaryContent) return;

        setIsSubmittingSummary(true);
        try {
            await updateRdvSummary(selectedRdvId, summaryContent);

            // Refresh data
            if (id) {
                const fetchedRdvs = await getStudentRdvs(id);
                setRdvs(fetchedRdvs);
            }

            setSummaryContent('');
            setSelectedRdvId('');
            setActiveTab('historique');
        } catch (error) {
            console.error("Failed to save summary", error);
            alert("Erreur lors de l'enregistrement du compte-rendu.");
        } finally {
            setIsSubmittingSummary(false);
        }
    };

    const activeTasks = tasks.filter(task => !task.completed).length;
    const completedTasks = tasks.filter(task => task.completed).length;

    return (
        <>
            <HeaderAdmin />
            <div className="min-h-screen bg-white py-8 px-6">
                {isLoading ? (
                    <div className="flex justify-center items-center h-64">
                        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-brand"></div>
                    </div>
                ) : (
                    <div className="container mx-auto max-w-7xl">
                        {/* Header with Back Button */}
                        <div className="mb-6">
                            <Link
                                to="/admin/gestion-etudiants"
                                className="inline-flex items-center text-brand hover:text-brand-400 transition-colors mb-4"
                            >
                                <ArrowLeft className="w-5 h-5 mr-2" />
                                <span className="font-medium">Retour</span>
                            </Link>
                            <div>
                                <h1 className="text-3xl font-bold text-gray-900">Profil de {studentInfo.fullName}</h1>
                                <div className="flex items-center gap-2 mt-1">
                                    <p className="text-gray-500 font-medium">Gestion complète du dossier étudiant</p>
                                    {studentInfo.status && (
                                        <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${studentInfo.status === 'validation' ? 'bg-green-100 text-green-700' :
                                            studentInfo.status === 'Étudiant' ? 'bg-blue-100 text-blue-700' :
                                                'bg-yellow-100 text-yellow-700'
                                            }`}>
                                            {studentInfo.status}
                                        </span>
                                    )}
                                </div>
                            </div>
                        </div>

                        {/* Main Grid */}
                        <div className="grid lg:grid-cols-3 gap-8">
                            {/* Left Column - Student Info */}
                            <div className="lg:col-span-2 space-y-8">
                                {/* Personal Information */}
                                <div className="bg-white rounded-2xl border border-gray-200 shadow-sm p-8">
                                    <div className="flex items-center justify-between mb-6">
                                        <div>
                                            <h2 className="text-xl font-bold text-brand mb-1">Informations personnelles</h2>
                                            <p className="text-sm text-gray-500">Détails et coordonnées de l'étudiant</p>
                                        </div>
                                        <button
                                            onClick={() => setIsEditModalOpen(true)}
                                            className="inline-flex items-center gap-2 px-4 py-2 bg-white border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors"
                                        >
                                            <Edit className="w-4 h-4" />
                                            Modifier
                                        </button>
                                    </div>

                                    <div className="grid md:grid-cols-2 gap-6">
                                        <div>
                                            <label className="text-sm font-semibold text-gray-600">Nom complet</label>
                                            <p className="text-base text-gray-900 mt-1">{studentInfo.fullName}</p>
                                        </div>
                                        <div>
                                            <label className="text-sm font-semibold text-gray-600">Date de naissance</label>
                                            <p className="text-base text-gray-900 mt-1">{studentInfo.birthDate}</p>
                                        </div>
                                        <div>
                                            <label className="text-sm font-semibold text-gray-600">Email</label>
                                            <p className="text-base text-gray-900 mt-1">{studentInfo.email}</p>
                                        </div>
                                        <div>
                                            <label className="text-sm font-semibold text-gray-600">Téléphone</label>
                                            <p className="text-base text-gray-900 mt-1">{studentInfo.phone}</p>
                                        </div>
                                        <div className="md:col-span-2">
                                            <label className="text-sm font-semibold text-gray-600">Adresse</label>
                                            <p className="text-base text-gray-900 mt-1">{studentInfo.address}</p>
                                        </div>
                                        <div>
                                            <label className="text-sm font-semibold text-gray-600">Université</label>
                                            <p className="text-base text-gray-900 mt-1">{studentInfo.university}</p>
                                        </div>
                                        <div>
                                            <label className="text-sm font-semibold text-gray-600">Filière</label>
                                            <p className="text-base text-gray-900 mt-1">{studentInfo.filiere}</p>
                                        </div>
                                        <div>
                                            <label className="text-sm font-semibold text-gray-600">Type de handicap</label>
                                            <p className="inline-block px-3 py-1 bg-blue-50 text-brand rounded-full text-sm font-medium mt-1">
                                                {studentInfo.handicapType}
                                            </p>
                                        </div>
                                        <div>
                                            <label className="text-sm font-semibold text-gray-600">Date d'inscription</label>
                                            <p className="text-base text-gray-900 mt-1">{studentInfo.inscriptionDate}</p>
                                        </div>
                                    </div>
                                </div>

                                {/* Notes Section */}
                                <div className="bg-white rounded-2xl border border-gray-200 shadow-sm p-8">
                                    <div className="mb-6">
                                        <h2 className="text-xl font-bold text-brand mb-1">Notes des rendez-vous</h2>
                                        <p className="text-sm text-gray-500">Historique et comptes-rendus des rendez-vous passés</p>
                                    </div>

                                    {/* Tabs */}
                                    <div className="flex items-center gap-4 border-b border-gray-200 mb-6">
                                        <button
                                            onClick={() => setActiveTab('historique')}
                                            className={`pb-3 px-1 font-medium transition-colors relative ${activeTab === 'historique'
                                                ? 'text-brand border-b-2 border-brand'
                                                : 'text-gray-500 hover:text-gray-700'
                                                }`}
                                        >
                                            Historique
                                        </button>
                                        <button
                                            onClick={() => setActiveTab('nouveau')}
                                            className={`pb-3 px-1 font-medium transition-colors relative ${activeTab === 'nouveau'
                                                ? 'text-brand border-b-2 border-brand'
                                                : 'text-gray-500 hover:text-gray-700'
                                                }`}
                                        >
                                            Nouveau compte-rendu
                                        </button>
                                    </div>

                                    {/* Tab Content */}
                                    {activeTab === 'historique' && (
                                        <div className="space-y-5">
                                            {rdvs.filter(r => r.status === 'Réalisé' || r.isPast).length === 0 ? (
                                                <p className="text-gray-500 text-center py-4">Aucun rendez-vous passé ou réalisé.</p>
                                            ) : (
                                                rdvs.filter(r => r.status === 'Réalisé' || r.isPast).map((rdv) => (
                                                    <div key={rdv.id} className="border border-gray-200 rounded-xl p-5">
                                                        <div className="flex items-start justify-between mb-3">
                                                            <div className="flex items-center gap-3">
                                                                <div className="p-2 bg-blue-50 rounded-lg">
                                                                    <Calendar className="w-5 h-5 text-brand" />
                                                                </div>
                                                                <div>
                                                                    <p className="font-bold text-gray-900">{rdv.date}</p>
                                                                    <p className="text-sm text-gray-500">{rdv.type}</p>
                                                                </div>
                                                            </div>
                                                        </div>
                                                        <p className="text-gray-700 leading-relaxed mb-3">
                                                            <span className="font-semibold block mb-1">Résumé :</span>
                                                            {rdv.notes}
                                                        </p>
                                                        <p className="text-xs text-gray-400">Lieu: {rdv.lieu}</p>
                                                    </div>
                                                ))
                                            )}
                                        </div>
                                    )}

                                    {activeTab === 'nouveau' && (
                                        <div className="space-y-5">
                                            <div className="bg-blue-50 border border-blue-100 rounded-lg p-4 mb-4">
                                                <p className="text-sm text-blue-800">
                                                    Sélectionnez un rendez-vous pour ajouter ou modifier son compte-rendu.
                                                </p>
                                            </div>

                                            <div>
                                                <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                    Rendez-vous concerné
                                                </label>
                                                <select
                                                    value={selectedRdvId}
                                                    onChange={(e) => {
                                                        const rId = e.target.value;
                                                        setSelectedRdvId(rId);
                                                        if (rId) {
                                                            const r = rdvs.find(rd => rd.id === rId);
                                                            setSummaryContent(r?.notes === "Aucun compte-rendu disponible." ? "" : r?.notes || "");
                                                        } else {
                                                            setSummaryContent("");
                                                        }
                                                    }}
                                                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent bg-white"
                                                >
                                                    <option value="">Sélectionner un rendez-vous...</option>
                                                    {rdvs.map(r => (
                                                        <option key={r.id} value={r.id}>
                                                            {r.date} - {r.type} ({r.status})
                                                        </option>
                                                    ))}
                                                </select>
                                            </div>

                                            <div>
                                                <label className="block text-sm font-semibold text-gray-700 mb-2">
                                                    Compte-rendu du rendez-vous
                                                </label>
                                                <textarea
                                                    rows={6}
                                                    placeholder="Décrivez le déroulement du rendez-vous..."
                                                    value={summaryContent}
                                                    onChange={(e) => setSummaryContent(e.target.value)}
                                                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent resize-none"
                                                />
                                            </div>
                                            <button
                                                onClick={handleSaveSummary}
                                                disabled={!selectedRdvId || !summaryContent || isSubmittingSummary}
                                                className={`w-full py-3 font-semibold rounded-lg transition-colors ${!selectedRdvId || !summaryContent || isSubmittingSummary
                                                    ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                                                    : 'bg-brand hover:bg-brand-400 text-white'
                                                    }`}
                                            >
                                                {isSubmittingSummary ? 'Enregistrement...' : 'Enregistrer le compte-rendu'}
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* Right Column - Tasks */}
                            <div className="lg:col-span-1">
                                <div className="bg-white rounded-2xl border border-gray-200 shadow-sm p-6 sticky top-8">
                                    <div className="mb-6">
                                        <h2 className="text-xl font-bold text-brand mb-1">Liste de tâches</h2>
                                        <p className="text-sm text-gray-500">Suivi des actions à entreprendre</p>
                                    </div>

                                    {/* New Task Button */}
                                    <button
                                        onClick={() => setIsNewTaskModalOpen(true)}
                                        className="w-full flex items-center justify-center gap-2 py-3 bg-accent hover:bg-accent-400 text-brand font-semibold rounded-lg transition-colors mb-6"
                                    >
                                        <Plus className="w-5 h-5" />
                                        Nouvelle tâche
                                    </button>

                                    {/* Task Stats */}
                                    <div className="flex gap-4 mb-6">
                                        <div className="flex-1">
                                            <p className="text-sm text-gray-500">Tâches actives</p>
                                            <p className="text-2xl font-bold text-brand">{activeTasks}</p>
                                        </div>
                                        <div className="flex-1">
                                            <p className="text-sm text-gray-500">Tâches terminées</p>
                                            <p className="text-2xl font-bold text-green-600">{completedTasks}</p>
                                        </div>
                                    </div>

                                    {/* Tasks List */}
                                    <div className="space-y-4">
                                        {tasks.map((task) => (
                                            <div
                                                key={task.id}
                                                className={`p-4 border rounded-xl transition-all ${task.completed
                                                    ? 'border-green-200 bg-green-50'
                                                    : 'border-gray-200 bg-white hover:shadow-md'
                                                    }`}
                                            >
                                                <div className="flex items-start justify-between gap-3">
                                                    <div className="flex items-start gap-3 flex-1">
                                                        <input
                                                            type="checkbox"
                                                            checked={task.completed}
                                                            onChange={async () => {
                                                                // Optimistic
                                                                const newStatus = !task.completed;
                                                                setTasks(tasks.map(t => t.id === task.id ? { ...t, completed: newStatus } : t));
                                                                try {
                                                                    await updateTaskStatus(task.id, newStatus);
                                                                } catch (e) {
                                                                    // Revert
                                                                    setTasks(tasks.map(t => t.id === task.id ? { ...t, completed: !newStatus } : t));
                                                                }
                                                            }}
                                                            className="mt-1 w-5 h-5 rounded border-gray-300 text-brand focus:ring-brand"
                                                        />
                                                        <div className="flex-1">
                                                            <p
                                                                className={`font-medium text-sm ${task.completed
                                                                    ? 'text-gray-400 line-through'
                                                                    : 'text-gray-900'
                                                                    }`}
                                                            >
                                                                {task.title}
                                                            </p>
                                                            <p className="text-xs text-gray-400 mt-1">{task.date}</p>
                                                        </div>
                                                    </div>
                                                    <button
                                                        onClick={() => handleDeleteTask(task.id)}
                                                        className="p-1 text-red-500 hover:bg-red-50 rounded transition-colors"
                                                    >
                                                        <Trash2 className="w-4 h-4" />
                                                    </button>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* Accessibility Button */}
                <Oeil />
            </div>

            {/* Edit Student Modal */}
            {isEditModalOpen && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                        <div className="sticky top-0 bg-white border-b border-gray-200 px-8 py-6 flex items-center justify-between">
                            <h2 className="text-2xl font-bold text-brand">Informations personnelles</h2>
                            <div className="flex items-center gap-3">
                                <button
                                    onClick={() => setIsEditModalOpen(false)}
                                    className="px-5 py-2 bg-brand text-white font-semibold rounded-lg hover:bg-brand-400 transition-colors"
                                >
                                    Enregistrer
                                </button>
                                <button
                                    onClick={() => setIsEditModalOpen(false)}
                                    className="px-5 py-2 border border-gray-300 text-gray-700 font-semibold rounded-lg hover:bg-gray-50 transition-colors"
                                >
                                    Annuler
                                </button>
                            </div>
                        </div>

                        <div className="p-8">
                            <p className="text-sm text-gray-500 mb-6">Détails et coordonnées de l'étudiant</p>

                            <div className="grid md:grid-cols-2 gap-6">
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                                        Nom complet
                                    </label>
                                    <input
                                        type="text"
                                        value={studentInfo.fullName}
                                        onChange={(e) => setStudentInfo({ ...studentInfo, fullName: e.target.value })}
                                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                                        Date de naissance
                                    </label>
                                    <input
                                        type="text"
                                        value={studentInfo.birthDate}
                                        onChange={(e) => setStudentInfo({ ...studentInfo, birthDate: e.target.value })}
                                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                                        Email
                                    </label>
                                    <input
                                        type="email"
                                        value={studentInfo.email}
                                        onChange={(e) => setStudentInfo({ ...studentInfo, email: e.target.value })}
                                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                                        Téléphone
                                    </label>
                                    <input
                                        type="tel"
                                        value={studentInfo.phone}
                                        onChange={(e) => setStudentInfo({ ...studentInfo, phone: e.target.value })}
                                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent"
                                    />
                                </div>
                                <div className="md:col-span-2">
                                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                                        Adresse
                                    </label>
                                    <input
                                        type="text"
                                        value={studentInfo.address}
                                        onChange={(e) => setStudentInfo({ ...studentInfo, address: e.target.value })}
                                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                                        Université
                                    </label>
                                    <input
                                        type="text"
                                        value={studentInfo.university}
                                        onChange={(e) => setStudentInfo({ ...studentInfo, university: e.target.value })}
                                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                                        Filière
                                    </label>
                                    <input
                                        type="text"
                                        value={studentInfo.filiere}
                                        onChange={(e) => setStudentInfo({ ...studentInfo, filiere: e.target.value })}
                                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                                        Type de handicap
                                    </label>
                                    <input
                                        type="text"
                                        value={studentInfo.handicapType}
                                        onChange={(e) => setStudentInfo({ ...studentInfo, handicapType: e.target.value })}
                                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                                        Date d'inscription
                                    </label>
                                    <input
                                        type="text"
                                        value={studentInfo.inscriptionDate}
                                        onChange={(e) => setStudentInfo({ ...studentInfo, inscriptionDate: e.target.value })}
                                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent"
                                    />
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* New Task Modal */}
            {isNewTaskModalOpen && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full">
                        <div className="bg-white border-b border-gray-200 px-8 py-6 flex items-center justify-between rounded-t-2xl">
                            <h2 className="text-2xl font-bold text-brand">Nouvelle tâche</h2>
                            <button
                                onClick={() => setIsNewTaskModalOpen(false)}
                                className="text-gray-400 hover:text-gray-600 transition-colors"
                            >
                                <Plus className="w-6 h-6 rotate-45" />
                            </button>
                        </div>

                        <div className="p-8">
                            <div className="space-y-5">
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                                        Titre de la tâche
                                    </label>
                                    <input
                                        type="text"
                                        placeholder="Ex: Renouveler le certificat MDPH"
                                        value={newTask.title}
                                        onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
                                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                                        Date d'échéance
                                    </label>
                                    <input
                                        type="date"
                                        value={newTask.date}
                                        onChange={(e) => setNewTask({ ...newTask, date: e.target.value })}
                                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent"
                                    />
                                </div>
                            </div>

                            <div className="flex gap-3 mt-6">
                                <button
                                    onClick={handleAddTask}
                                    className="flex-1 py-3 bg-brand hover:bg-brand-400 text-white font-semibold rounded-lg transition-colors"
                                >
                                    Ajouter
                                </button>
                                <button
                                    onClick={() => {
                                        setNewTask({ title: '', date: '' });
                                        setIsNewTaskModalOpen(false);
                                    }}
                                    className="flex-1 py-3 border border-gray-300 text-gray-700 font-semibold rounded-lg hover:bg-gray-50 transition-colors"
                                >
                                    Annuler
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            <FooterMain />
        </>
    );
};

export default DetailEtudiant;

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import HeaderClient from '../components/HeaderClient';
import FooterMain from '../components/FooterMain';
import Oeil from '../components/Oeil';
import { getDocumentation, DocumentationData } from '../services/airtable';
import { FileText, ExternalLink, X } from 'lucide-react';

function Documentation() {
    const navigate = useNavigate();
    const [docs, setDocs] = useState<DocumentationData[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedDoc, setSelectedDoc] = useState<DocumentationData | null>(null);

    useEffect(() => {
        const storedUser = localStorage.getItem('user');
        if (storedUser) {
            const parsedUser = JSON.parse(storedUser);
            // If Student, pass ID to filter.
            // If the user role is 'Etudiant', we pass the ID.
            if (parsedUser.id) {
                getDocumentation(parsedUser.id).then(data => {
                    setDocs(data);
                    setLoading(false);
                });
            }
        } else {
            navigate('/connexion');
        }
    }, [navigate]);

    return (
        <>
            <HeaderClient />
            <div className="min-h-screen bg-gray-50 py-12 px-6">
                <div className="container mx-auto max-w-7xl">
                    <div className="mb-10">
                        <h1 className="text-4xl font-extrabold text-gray-900 mb-2">Documentation</h1>
                        <p className="text-gray-500 text-lg">Ressources et guides mis à votre disposition.</p>
                    </div>

                    {loading ? (
                        <div className="text-center py-20">
                            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                            <p className="mt-4 text-gray-500">Chargement des documents...</p>
                        </div>
                    ) : docs.length === 0 ? (
                        <div className="text-center py-20 bg-white rounded-3xl shadow-sm border border-gray-100">
                            <FileText className="h-16 w-16 text-gray-300 mx-auto mb-4" />
                            <h3 className="text-xl font-bold text-gray-900">Aucune documentation disponible</h3>
                            <p className="text-gray-500 mt-2">Vous n'avez accès à aucun document pour le moment.</p>
                        </div>
                    ) : (
                        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
                            {docs.map((doc) => (
                                <div
                                    key={doc.id}
                                    className="bg-white rounded-2xl shadow-sm hover:shadow-xl transition-all duration-300 border border-gray-100 overflow-hidden flex flex-col cursor-pointer group"
                                    onClick={() => setSelectedDoc(doc)}
                                >
                                    <div className="p-8 flex-1">
                                        <div className="flex items-start justify-between mb-4">
                                            <div className="p-3 bg-blue-50 text-blue-600 rounded-xl group-hover:bg-blue-600 group-hover:text-white transition-colors">
                                                <FileText className="w-6 h-6" />
                                            </div>
                                            {doc.lien && <ExternalLink className="w-5 h-5 text-gray-300" />}
                                        </div>
                                        <h3 className="text-xl font-bold text-gray-900 mb-3 line-clamp-2 group-hover:text-blue-600 transition-colors">
                                            {doc.titre}
                                        </h3>
                                        <p className="text-gray-500 leading-relaxed line-clamp-3">
                                            {doc.description}
                                        </p>
                                    </div>
                                    <div className="bg-gray-50 px-8 py-4 border-t border-gray-100 flex items-center justify-between">
                                        <span className="text-sm font-medium text-blue-600 group-hover:translate-x-1 transition-transform inline-flex items-center gap-1">
                                            Consulter
                                        </span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                {/* Modal */}
                {selectedDoc && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
                        <div
                            className="bg-white rounded-3xl w-full max-w-2xl max-h-[90vh] overflow-y-auto shadow-2xl animate-in zoom-in-95 duration-200"
                            onClick={(e) => e.stopPropagation()}
                        >
                            <div className="p-8">
                                <div className="flex items-start justify-between mb-6">
                                    <h2 className="text-2xl font-bold text-gray-900 pr-8">
                                        {selectedDoc.titre}
                                    </h2>
                                    <button
                                        onClick={() => setSelectedDoc(null)}
                                        className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-500 hover:text-gray-900"
                                    >
                                        <X className="w-6 h-6" />
                                    </button>
                                </div>

                                <div className="prose prose-blue max-w-none text-gray-700">
                                    {selectedDoc.description && (
                                        <div className="mb-6 text-lg text-gray-600 leading-relaxed border-b border-gray-100 pb-6">
                                            {selectedDoc.description}
                                        </div>
                                    )}

                                    {selectedDoc.contenu && (
                                        <div className="mb-8 whitespace-pre-wrap leading-relaxed">
                                            {selectedDoc.contenu}
                                        </div>
                                    )}

                                    {selectedDoc.lien && (
                                        <a
                                            href={selectedDoc.lien.startsWith('http') ? selectedDoc.lien : `https://${selectedDoc.lien}`}
                                            target="_blank"
                                            rel="noopener noreferrer"
                                            className="inline-flex items-center gap-2 px-6 py-3 bg-blue-600 text-white font-semibold rounded-xl hover:bg-blue-700 transition-colors shadow-lg shadow-blue-600/20"
                                        >
                                            <ExternalLink className="w-4 h-4" />
                                            Accéder à la ressource externe
                                        </a>
                                    )}

                                    {!selectedDoc.contenu && !selectedDoc.lien && (
                                        <p className="text-gray-400 italic">Aucun contenu supplémentaire disponible.</p>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                <Oeil />
            </div>
            <FooterMain />
        </>
    );
}

export default Documentation;

import { useState, useEffect } from 'react';
import HeaderAdmin from '../components/HeaderAdmin';
import FooterMain from '../components/FooterMain';
import Oeil from '../components/Oeil';
import {
    getDocumentation,
    createDocumentation,
    deleteDocumentation,
    getAllStudents,
    DocumentationData
} from '../services/airtable';
import { Trash2, Plus, ExternalLink, Check, Search, X } from 'lucide-react';

function DocumentationAdmin() {
    const [docs, setDocs] = useState<DocumentationData[]>([]);
    const [students, setStudents] = useState<any[]>([]); // Using any for student structure based on service
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [searchTerm, setSearchTerm] = useState("");

    // Form State
    const [newDoc, setNewDoc] = useState({
        titre: '',
        description: '',
        contenu: '',
        lien: '',
        sharedWithIds: [] as string[],
        shareMode: 'all' as 'all' | 'select'
    });

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setLoading(true);
        try {
            const [fetchedDocs, fetchedStudents] = await Promise.all([
                getDocumentation(), // Fetch all docs for admin
                getAllStudents()
            ]);
            setDocs(fetchedDocs);
            setStudents(fetchedStudents);
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (window.confirm("Êtes-vous sûr de vouloir supprimer ce document ?")) {
            try {
                await deleteDocumentation(id);
                setDocs(docs.filter(d => d.id !== id));
            } catch (error) {
                alert("Erreur lors de la suppression");
            }
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            const sharedIds = newDoc.shareMode === 'all' ? [] : newDoc.sharedWithIds;

            await createDocumentation({
                titre: newDoc.titre,
                description: newDoc.description,
                contenu: newDoc.contenu,
                lien: newDoc.lien,
                sharedWithIds: sharedIds,
                adminName: "Admin" // Simple default, could be dynamic
            });

            setIsModalOpen(false);
            setNewDoc({
                titre: '',
                description: '',
                contenu: '',
                lien: '',
                sharedWithIds: [],
                shareMode: 'all'
            });
            fetchData(); // Refresh list
        } catch (error: any) {
            console.error("Create detailed error:", error);
            const msg = error?.error || error?.message || JSON.stringify(error);
            alert("Erreur lors de la création: " + msg);
        }
    };

    const toggleStudentSelection = (studentId: string) => {
        setNewDoc(prev => {
            const exists = prev.sharedWithIds.includes(studentId);
            if (exists) {
                return { ...prev, sharedWithIds: prev.sharedWithIds.filter(id => id !== studentId) };
            } else {
                return { ...prev, sharedWithIds: [...prev.sharedWithIds, studentId] };
            }
        });
    };



    const filteredStudents = students.filter(s =>
        s.nomComplet.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="min-h-screen bg-gray-50 flex flex-col">
            <HeaderAdmin />

            <main className="flex-grow container mx-auto px-4 py-8 max-w-7xl">
                <div className="flex justify-between items-center mb-8">
                    <div>
                        <h1 className="text-3xl font-bold text-gray-900">Gestion de la Documentation</h1>
                        <p className="text-gray-500 mt-1">Gérez les ressources partagées avec les étudiants</p>
                    </div>
                    <div className="flex gap-3">

                        <button
                            onClick={() => setIsModalOpen(true)}
                            className="bg-blue-600 text-white px-5 py-2.5 rounded-xl font-medium flex items-center gap-2 hover:bg-blue-700 transition-colors shadow-sm"
                        >
                            <Plus className="w-5 h-5" />
                            Ajouter
                        </button>
                    </div>
                </div>

                <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="bg-gray-50 border-b border-gray-100">
                                <tr>
                                    <th className="px-6 py-4 font-semibold text-gray-700 text-sm">Titre</th>
                                    <th className="px-6 py-4 font-semibold text-gray-700 text-sm">Description</th>
                                    <th className="px-6 py-4 font-semibold text-gray-700 text-sm">Visibilité</th>
                                    <th className="px-6 py-4 font-semibold text-gray-700 text-sm">Lien</th>
                                    <th className="px-6 py-4 font-semibold text-gray-700 text-sm text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-50">
                                {loading ? (
                                    <tr>
                                        <td colSpan={5} className="px-6 py-8 text-center text-gray-500">Chargement...</td>
                                    </tr>
                                ) : docs.length === 0 ? (
                                    <tr>
                                        <td colSpan={5} className="px-6 py-8 text-center text-gray-500">Aucun document trouvé.</td>
                                    </tr>
                                ) : (
                                    docs.map((doc) => (
                                        <tr key={doc.id} className="hover:bg-gray-50 transition-colors">
                                            <td className="px-6 py-4 font-medium text-gray-900">{doc.titre}</td>
                                            <td className="px-6 py-4 text-gray-500 max-w-xs truncate">{doc.description}</td>
                                            <td className="px-6 py-4">
                                                {doc.sharedWithIds.length === 0 ? (
                                                    <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">
                                                        Tout le monde
                                                    </span>
                                                ) : (
                                                    <div className="flex flex-col gap-1">
                                                        {doc.sharedWithIds.map(id => {
                                                            const student = students.find(s => s.id === id);
                                                            return (
                                                                <span key={id} className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800 w-fit">
                                                                    {student ? student.nomComplet : 'Etudiant inconnu'}
                                                                </span>
                                                            );
                                                        })}
                                                    </div>
                                                )}
                                            </td>
                                            <td className="px-6 py-4">
                                                {doc.lien && (
                                                    <a href={doc.lien} target="_blank" rel="noopener noreferrer" className="text-blue-600 hover:text-blue-800">
                                                        <ExternalLink className="w-4 h-4" />
                                                    </a>
                                                )}
                                            </td>
                                            <td className="px-6 py-4 text-right">
                                                <button
                                                    onClick={() => handleDelete(doc.id)}
                                                    className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                                    title="Supprimer"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </button>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </main>

            {/* Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
                    <div className="bg-white rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto shadow-xl flex flex-col">
                        <div className="p-6 border-b border-gray-100 flex items-center justify-between">
                            <h2 className="text-xl font-bold text-gray-900">Nouveau Document</h2>
                            <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-gray-600">
                                <X className="w-6 h-6" />
                            </button>
                        </div>

                        <form onSubmit={handleSubmit} className="p-6 space-y-6">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Titre</label>
                                <input
                                    type="text"
                                    required
                                    className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500"
                                    value={newDoc.titre}
                                    onChange={e => setNewDoc({ ...newDoc, titre: e.target.value })}
                                    placeholder="Ex: TDAH - Comprendre les symptômes"
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Description (Courte)</label>
                                <textarea
                                    rows={2}
                                    className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500"
                                    value={newDoc.description}
                                    onChange={e => setNewDoc({ ...newDoc, description: e.target.value })}
                                    placeholder="Une brève description pour l'aperçu..."
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Contenu (Détaillé)</label>
                                <textarea
                                    rows={6}
                                    className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500"
                                    value={newDoc.contenu}
                                    onChange={e => setNewDoc({ ...newDoc, contenu: e.target.value })}
                                    placeholder="Le contenu complet du document..."
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Lien externe</label>
                                <div className="relative">
                                    <ExternalLink className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                    <input
                                        type="text"
                                        className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500"
                                        value={newDoc.lien}
                                        onChange={e => setNewDoc({ ...newDoc, lien: e.target.value })}
                                        placeholder="https://..."
                                    />
                                </div>
                            </div>

                            <div className="pt-4 border-t border-gray-100">
                                <label className="block text-sm font-medium text-gray-700 mb-3">Partager avec</label>

                                <div className="flex gap-4 mb-4">
                                    <label className="flex items-center gap-2 cursor-pointer">
                                        <input
                                            type="radio"
                                            name="shareMode"
                                            checked={newDoc.shareMode === 'all'}
                                            onChange={() => setNewDoc({ ...newDoc, shareMode: 'all' })}
                                            className="w-4 h-4 text-blue-600 focus:ring-blue-500"
                                        />
                                        <span className="text-gray-700">Tous les étudiants</span>
                                    </label>
                                    <label className="flex items-center gap-2 cursor-pointer">
                                        <input
                                            type="radio"
                                            name="shareMode"
                                            checked={newDoc.shareMode === 'select'}
                                            onChange={() => setNewDoc({ ...newDoc, shareMode: 'select' })}
                                            className="w-4 h-4 text-blue-600 focus:ring-blue-500"
                                        />
                                        <span className="text-gray-700">Sélectionner des étudiants</span>
                                    </label>
                                </div>

                                {newDoc.shareMode === 'select' && (
                                    <div className="border border-gray-200 rounded-xl overflow-hidden">
                                        <div className="p-3 border-b border-gray-100 bg-gray-50 flex items-center gap-2">
                                            <Search className="w-4 h-4 text-gray-400" />
                                            <input
                                                type="text"
                                                placeholder="Rechercher un étudiant..."
                                                value={searchTerm}
                                                onChange={(e) => setSearchTerm(e.target.value)}
                                                className="bg-transparent border-none focus:outline-none text-sm w-full"
                                            />
                                        </div>
                                        <div className="max-h-48 overflow-y-auto p-2 space-y-1">
                                            {filteredStudents.length === 0 ? (
                                                <p className="text-sm text-gray-400 text-center py-2">Aucun étudiant trouvé.</p>
                                            ) : (
                                                filteredStudents.map(student => (
                                                    <label key={student.id} className="flex items-center gap-3 p-2 hover:bg-gray-50 rounded-lg cursor-pointer transition-colors">
                                                        <div className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${newDoc.sharedWithIds.includes(student.id) ? 'bg-blue-600 border-blue-600' : 'border-gray-300 bg-white'
                                                            }`}>
                                                            {newDoc.sharedWithIds.includes(student.id) && <Check className="w-3 h-3 text-white" />}
                                                        </div>
                                                        <input
                                                            type="checkbox"
                                                            className="hidden"
                                                            checked={newDoc.sharedWithIds.includes(student.id)}
                                                            onChange={() => toggleStudentSelection(student.id)}
                                                        />
                                                        <span className="text-sm text-gray-700">{student.nomComplet}</span>
                                                    </label>
                                                ))
                                            )}
                                        </div>
                                    </div>
                                )}
                            </div>

                            <div className="pt-6 flex justify-end gap-3">
                                <button
                                    type="button"
                                    onClick={() => setIsModalOpen(false)}
                                    className="px-5 py-2.5 text-gray-700 font-medium hover:bg-gray-100 rounded-xl transition-colors"
                                >
                                    Annuler
                                </button>
                                <button
                                    type="submit"
                                    className="px-5 py-2.5 bg-blue-600 text-white font-medium rounded-xl hover:bg-blue-700 transition-colors shadow-lg shadow-blue-600/20"
                                >
                                    Créer le document
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            <Oeil />
            <FooterMain />
        </div>
    );
}

export default DocumentationAdmin;

