import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Calendar, Clock } from 'lucide-react';
import HeaderClient from '../components/HeaderClient';
import FooterMain from '../components/FooterMain';
import Oeil from '../components/Oeil';
import { getTasksForStudent, updateTaskStatus, Task, getStudentRdvs, StudentRdv } from '../services/airtable';
import CalendarWidget from '../components/CalendarWidget';

function EspaceEtudiant() {
    const navigate = useNavigate();
    const [user, setUser] = useState<any>(null);
    const [tasks, setTasks] = useState<Task[]>([]);
    const [rdvs, setRdvs] = useState<StudentRdv[]>([]);
    const [loadingTasks, setLoadingTasks] = useState(true);


    useEffect(() => {
        // Load user from local storage
        const storedUser = localStorage.getItem('user');
        if (storedUser) {
            const parsedUser = JSON.parse(storedUser);
            setUser(parsedUser);

            // Load tasks for this student
            if (parsedUser.id) {
                // Fetch Tasks
                getTasksForStudent(parsedUser.id).then(fetchedTasks => {
                    setTasks(fetchedTasks);
                    setLoadingTasks(false);
                });

                // Fetch RDVs
                getStudentRdvs(parsedUser.id).then(fetchedRdvs => {
                    setRdvs(fetchedRdvs);
                });
            }
        } else {
            // Redirect to login if not logged in
            navigate('/connexion');
        }
    }, [navigate]);

    const handleToggleTask = async (taskId: string, currentStatus: boolean) => {
        // Optimistic update
        setTasks(tasks.map(t =>
            t.id === taskId ? { ...t, completed: !currentStatus } : t
        ));

        try {
            await updateTaskStatus(taskId, !currentStatus);
        } catch (error) {
            console.error("Failed to update task", error);
            // Revert on error
            setTasks(tasks.map(t =>
                t.id === taskId ? { ...t, completed: currentStatus } : t
            ));
        }
    };




    const upcomingAppointments = rdvs.filter(r => !r.isPast && (r.status === 'Attente de Validation' || r.status === 'Prévu')).sort((a, b) => new Date(a.rawDate).getTime() - new Date(b.rawDate).getTime());
    const pastAppointments = rdvs.filter(r => r.isPast).sort((a, b) => new Date(b.rawDate).getTime() - new Date(a.rawDate).getTime());

    return (
        <>
            <HeaderClient />
            <div className="min-h-screen bg-white py-8 px-6">
                <div className="container mx-auto max-w-7xl">
                    {/* Welcome Section */}
                    <div className="mb-8">
                        <h1 className="text-3xl font-bold text-gray-900 mb-1">
                            Bonjour, {user && user['Nom Complet'] ? user['Nom Complet'].split(' ')[0] : 'Etudiant'} ! 👋
                        </h1>
                        <p className="text-gray-500 font-medium">Espace personnel</p>
                    </div>

                    {/* Main Grid - Calendar and Tasks */}
                    <div className="grid lg:grid-cols-2 gap-8 mb-10">
                        {/* Calendar Section */}
                        <div className="bg-white rounded-3xl border border-gray-100 shadow-sm p-6">
                            <h2 className="text-2xl font-bold text-slate-800 mb-6">Mon calendrier</h2>
                            <div className="space-y-4">
                                <CalendarWidget highlightDates={rdvs.filter(r => r.status !== 'Annulé' && r.status !== 'Reporté').map(r => new Date(r.rawDate))} />
                            </div>
                        </div>


                        {/* Tasks Section */}
                        <div className="bg-white rounded-3xl border border-gray-100 shadow-sm p-8">
                            <div className="mb-6">
                                <h2 className="text-2xl font-bold text-slate-800">Ma liste de tâches</h2>
                                <p className="text-gray-500">Actions à réaliser</p>
                            </div>
                            <div className="space-y-4">
                                {loadingTasks ? (
                                    <p className="text-gray-500 text-sm">Chargement des tâches...</p>
                                ) : tasks.length === 0 ? (
                                    <p className="text-gray-500 text-sm">Aucune tâche à faire.</p>
                                ) : (
                                    tasks.map((task) => (
                                        <div
                                            key={task.id}
                                            className="flex items-start gap-4 p-4 bg-white rounded-xl border border-gray-100 shadow-sm hover:shadow-md transition-shadow"
                                        >
                                            <div className="pt-1">
                                                <input
                                                    type="checkbox"
                                                    checked={task.completed}
                                                    onChange={() => handleToggleTask(task.id, task.completed)}
                                                    className={`w-5 h-5 rounded border-gray-300 ${task.completed ? 'bg-slate-800 text-slate-800' : 'text-slate-800'} focus:ring-slate-800`}
                                                />
                                            </div>
                                            <div className="flex-1">
                                                <p
                                                    className={`font-semibold text-base ${task.completed
                                                        ? 'text-gray-400 line-through'
                                                        : 'text-gray-800'
                                                        }`}
                                                >
                                                    {task.title}
                                                </p>
                                                <p className="text-xs text-gray-400 flex items-center gap-1 mt-2 font-medium">
                                                    <Clock className="w-3 h-3" />
                                                    {task.date}
                                                </p>
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    </div>

                    {/* Past Appointments Section */}
                    <div className="mb-10 bg-white rounded-3xl border border-gray-100 shadow-sm p-8">
                        <h2 className="text-2xl font-bold text-slate-800 mb-8">
                            Rendez-vous passés et compte rendu
                        </h2>
                        <div className="space-y-6">
                            {pastAppointments.map((appointment) => (
                                <div
                                    key={appointment.id}
                                    className="bg-gray-50 rounded-xl p-6"
                                >
                                    <div className="flex flex-col md:flex-row md:items-center justify-between mb-4 gap-2">
                                        <h3 className="text-lg font-bold text-gray-900">
                                            {appointment.type}
                                        </h3>
                                        <div className="flex items-center text-gray-500 text-sm font-medium">
                                            <Calendar className="w-4 h-4 mr-2" />
                                            {appointment.date}
                                        </div>
                                    </div>

                                    <div className="flex gap-3">
                                        <div className="w-1 bg-slate-800 rounded-full shrink-0"></div>
                                        <div className="bg-blue-50/50 rounded-lg p-4 w-full">
                                            <p className="text-blue-600 font-semibold mb-1 text-sm">Notes :</p>
                                            <p className="text-slate-700 text-sm leading-relaxed">
                                                {appointment.notes}
                                            </p>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Upcoming Appointments Section */}
                    <div className="bg-white rounded-3xl border border-gray-100 shadow-sm p-8 mb-8">
                        <div className="flex items-center justify-between mb-2">
                            <h2 className="text-2xl font-bold text-slate-800">
                                Rendez-vous à venir
                            </h2>
                            <button
                                onClick={() => navigate('/prise-rdv')}
                                className="text-blue-600 hover:text-blue-700 font-semibold text-sm">
                                Voir tout
                            </button>
                        </div>
                        <p className="text-gray-500 mb-6">Prochaines sessions</p>

                        <div className="space-y-4">
                            {upcomingAppointments.map((appointment) => (
                                <div
                                    key={appointment.id}
                                    className="bg-gray-50 rounded-xl p-6 flex items-center justify-between"
                                >
                                    <div>
                                        <h3 className="text-lg font-bold text-gray-900 mb-2">
                                            {appointment.type}
                                        </h3>
                                        <p className="text-sm text-gray-500 flex items-center gap-2 font-medium">
                                            <Calendar className="w-4 h-4" />
                                            {appointment.date}
                                        </p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* Accessibility Button */}
                <Oeil />
            </div >
            <FooterMain />
        </>
    );
}

export default EspaceEtudiant;

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Mail, Loader } from 'lucide-react';
import HeaderInscription from '../components/HeaderInscription';
import FooterOther from '../components/FooterOther';
import { checkBookingEligibility } from '../services/airtable';

function FirstRdv() {
    const navigate = useNavigate();
    const [email, setEmail] = useState('');
    const [error, setError] = useState('');
    const [isChecking, setIsChecking] = useState(false);

    const validateEmail = (email: string) => {
        return String(email)
            .toLowerCase()
            .match(
                /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/
            );
    };

    const handleContinue = async () => {
        if (!email) {
            setError('L\'adresse email est obligatoire');
            return;
        }
        if (!validateEmail(email)) {
            setError('Veuillez entrer une adresse email valide');
            return;
        }

        setIsChecking(true);
        if (error) setError('');

        try {
            const eligibility = await checkBookingEligibility(email);

            if (!eligibility.allowed) {
                if (eligibility.reason === 'ACCOUNT_EXISTS') {
                    setError('Un compte existe déjà pour cette adresse email. Veuillez vous connecter à votre espace.');
                } else if (eligibility.reason === 'RDV_EXISTS') {
                    setError('Un rendez-vous est déjà programmé ou en cours de validation pour cette adresse.');
                }
                return;
            }

            // Navigate to appointment selection page with email
            navigate('/premier-rdv/selection', { state: { email } });
        } catch (err) {
            console.error(err);
            setError('Une erreur est survenue lors de la vérification.');
        } finally {
            setIsChecking(false);
        }
    };


    const handleBack = () => {
        navigate('/');
    };

    return (
        <>
            <div className="min-h-screen bg-accent-50 pt-6 pb-12 px-6 flex flex-col">
                <HeaderInscription />
                <div className="container mx-auto max-w-2xl flex-1 flex items-center justify-center py-8">
                    {/* Main Card */}
                    <div className="bg-white rounded-3xl shadow-xl p-8 md:p-12">
                        {/* Header Section */}
                        <div className="text-center mb-8">
                            <h1 className="text-3xl font-bold text-gray-900 mb-4">Premier contact</h1>
                            <p className="text-gray-600 leading-relaxed">
                                Bienvenue ! Pour commencer votre accompagnement, nous devons d'abord planifier un premier rendez-vous.
                            </p>
                        </div>

                        {/* Email Section */}
                        <div className="mb-8">
                            <div className="flex items-center gap-3 mb-4">
                                <div className="w-10 h-10 bg-brand rounded-lg flex items-center justify-center">
                                    <Mail className="w-5 h-5 text-white" />
                                </div>
                                <h2 className="text-lg font-bold text-gray-900">Vos coordonnées</h2>
                            </div>

                            <p className="text-gray-600 mb-4">
                                Veuillez nous indiquer votre adresse email pour poursuivre
                            </p>

                            <div className="mb-2">
                                <label htmlFor="email" className="block text-sm font-semibold text-gray-900 mb-2">
                                    Adresse email <span className="text-red-500">*</span>
                                </label>
                                <input
                                    type="email"
                                    id="email"
                                    value={email}
                                    onChange={(e) => {
                                        setEmail(e.target.value);
                                        if (error) setError('');
                                    }}
                                    disabled={isChecking}
                                    placeholder="example@gmail.com"
                                    className={`w-full px-4 py-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-brand focus:border-transparent ${error ? 'border-red-500' : 'border-gray-300'}`}
                                />
                                {error && <p className="text-red-500 text-sm mt-1">{error}</p>}
                            </div>

                            <p className="text-sm text-gray-500">
                                Cette adresse sera utilisée pour vous envoyer la confirmation de votre rendez-vous
                            </p>
                        </div>

                        {/* Next Steps Section */}
                        <div className="bg-blue-50 border border-blue-200 rounded-xl p-6 mb-8">
                            <h3 className="font-bold text-gray-900 mb-3">Prochaines étapes</h3>
                            <ul className="space-y-2 text-sm text-gray-700">
                                <li>Vous allez pouvoir choisir un créneau pour votre premier rendez-vous</li>
                                <li>Lors du rendez-vous, nous évaluerons vos besoins et créerons votre dossier</li>
                                <li>Vous recevrez ensuite vos identifiants pour accéder à votre espace personnel</li>
                            </ul>
                        </div>

                        {/* Action Buttons */}
                        <div className="flex justify-between gap-4">
                            <button
                                onClick={handleBack}
                                disabled={isChecking}
                                className="px-6 py-3 text-gray-700 font-medium rounded-lg border border-gray-300 hover:bg-gray-50 transition-colors disabled:opacity-50"
                            >
                                Retour
                            </button>
                            <button
                                onClick={handleContinue}
                                disabled={isChecking}
                                className="px-8 py-3 bg-brand text-white font-bold rounded-lg hover:bg-brand-600 transition-colors shadow-md flex items-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                            >
                                {isChecking ? (
                                    <>
                                        <Loader className="w-5 h-5 animate-spin" />
                                        Vérification...
                                    </>
                                ) : (
                                    <>
                                        Continuer
                                        <span>→</span>
                                    </>
                                )}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
            <FooterOther />
        </>
    );
}

export default FirstRdv;

import { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { ArrowLeft, Calendar as CalendarIcon, Clock, CheckCircle, X, MapPin, Video, MessageSquare } from 'lucide-react'; import HeaderMain from '../components/HeaderMain';
import FooterOther from '../components/FooterOther';
import { createRdv, generateAvailableSlots } from '../services/airtable';
import { sendRdvConfirmationEmail } from '../services/email';

function FirstRdvStep2() {
    const navigate = useNavigate();
    const location = useLocation();
    const email = location.state?.email || '';



    // State management
    const [selectedDate, setSelectedDate] = useState<Date | null>(null);
    const [selectedTime, setSelectedTime] = useState<string | null>(null);
    const [appointmentType, setAppointmentType] = useState<'presential' | 'video' | null>(null);
    const [comment, setComment] = useState('');
    const [showConfirmModal, setShowConfirmModal] = useState(false);
    const [currentMonth, setCurrentMonth] = useState(new Date());
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [availableSlots, setAvailableSlots] = useState<string[]>([]);
    const [slotsLoading, setSlotsLoading] = useState(false);

    useEffect(() => {
        const loadSlots = async () => {
            if (selectedDate && !isPastDate(selectedDate)) {
                setSlotsLoading(true);
                const slots = await generateAvailableSlots(selectedDate);
                setAvailableSlots(slots);
                setSlotsLoading(false);
            } else {
                setAvailableSlots([]);
            }
        };
        loadSlots();
    }, [selectedDate]);

    // Calendar helpers
    const getDaysInMonth = (date: Date) => {
        const year = date.getFullYear();
        const month = date.getMonth();
        const firstDay = new Date(year, month, 1);
        const lastDay = new Date(year, month + 1, 0);
        const daysInMonth = lastDay.getDate();
        const startingDayOfWeek = firstDay.getDay();

        return { daysInMonth, startingDayOfWeek };
    };

    const formatMonthYear = (date: Date) => {
        return date.toLocaleDateString('fr-FR', { month: 'long', year: 'numeric' });
    };

    const formatSelectedDate = (date: Date) => {
        return date.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
    };

    const isSameDay = (date1: Date | null, date2: Date) => {
        if (!date1) return false;
        return date1.getDate() === date2.getDate() &&
            date1.getMonth() === date2.getMonth() &&
            date1.getFullYear() === date2.getFullYear();
    };

    const isPastDate = (date: Date) => {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        return date < today;
    };

    const handleDateClick = (day: number) => {
        const newDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
        if (isPastDate(newDate)) return;

        setSelectedDate(newDate);
        setSelectedTime(null); // Reset time when date changes
    };

    const handlePrevMonth = () => {
        setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1));
    };

    const handleNextMonth = () => {
        setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1));
    };

    const handleConfirm = async () => {
        console.log("Confirm button clicked", { selectedDate, selectedTime, appointmentType, email });
        if (selectedDate && selectedTime && appointmentType) {
            setIsSubmitting(true);
            setError(null);

            try {
                // Parse time and combine with date
                const [hours, minutes] = selectedTime.split(':').map(Number);
                const rdvDate = new Date(selectedDate);
                rdvDate.setHours(hours, minutes);

                // Determine Lieu/Lien Visio based on type
                // User requirement: "Pour lien visio met rien s'il choisit en présentiel et ecrit lien meet sil chosit cette option"
                const lienVisio = appointmentType === 'video' ? 'https://meet.google.com/uva-tphn-spf' : '';
                const lieu = appointmentType === 'presential' ? 'Bureau Handepassement' : '';

                await createRdv({
                    date: rdvDate,
                    type: appointmentType === 'presential' ? 'Présentiel' : 'Visio',
                    status: 'Attente de Validation',
                    lieu: lieu,
                    lienVisio: lienVisio,
                    commentaires: comment,
                    studentEmail: email, // From location state
                    admin: 'Myriam'
                });

                // Send Confirmation Email
                // We'll calculate the formatted date again for the email
                const formattedDate = rdvDate.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });

                await sendRdvConfirmationEmail({
                    to_email: email,
                    to_name: "Étudiant", // We could fetch the name but email is enough for now, or "Étudiant"
                    date: formattedDate,
                    time: selectedTime,
                    type: appointmentType === 'presential' ? 'Présentiel' : 'Visio',
                    location: appointmentType === 'presential' ? 'Bureau Handepassement' : 'Google Meet',
                    notes: comment
                });

                setShowConfirmModal(true);
            } catch (err: any) {
                console.error("Erreur lors de la prise de rendez-vous:", err);
                // We don't block the UI if email fails but RDV succeeded, but ideally we should distinguish errors.
                // However, usually if createRdv succeeds, we want to show success modal.
                // If email fails, it will log to console.
                if (err.text) {
                    // EmailJS specific error often has 'text'
                    console.warn("Email sending failed but RDV created");
                    // We still show success modal as the main action (RDV) worked
                    setShowConfirmModal(true);
                } else {
                    setError("Une erreur est survenue lors de la création du rendez-vous. Veuillez réessayer ou contacter l'administration.");
                }
            } finally {
                setIsSubmitting(false);
            }
        }
    };

    const handleBackToHome = () => {
        navigate('/');
    };

    const { daysInMonth, startingDayOfWeek } = getDaysInMonth(currentMonth);
    const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
    const emptyDays = Array.from({ length: startingDayOfWeek === 0 ? 6 : startingDayOfWeek - 1 }, (_, i) => i);

    return (
        <>
            <div className="min-h-screen bg-accent-50 pt-6 pb-12 px-6 flex flex-col">
                <HeaderMain />
                <div className="container mx-auto max-w-6xl flex-1">
                    {/* Back Button */}
                    <button
                        onClick={() => navigate(-1)}
                        className="flex items-center gap-2 text-gray-700 mb-6 hover:text-brand transition-colors"
                    >
                        <ArrowLeft className="w-5 h-5" />
                        <span className="font-medium">Retour</span>
                    </button>

                    {/* Title */}
                    <h1 className="text-3xl font-bold text-gray-900 mb-2">Premier rendez-vous</h1>
                    <p className="text-gray-600 mb-8">Choisissez un créneau pour votre premier rendez-vous</p>

                    <div className="grid lg:grid-cols-3 gap-8">
                        <div className="lg:col-span-2 space-y-8">
                            {/* Appointment Type Section */}
                            <div className="bg-white rounded-3xl shadow-xl p-8">
                                <h2 className="text-xl font-bold text-gray-900 mb-2">Type de rendez-vous</h2>
                                <p className="text-sm text-gray-600 mb-6">Comment souhaitez-vous effectuer ce rendez-vous ?</p>

                                <div className="grid sm:grid-cols-2 gap-4">
                                    <button
                                        onClick={() => setAppointmentType('presential')}
                                        className={`p-4 rounded-xl border-2 transition-all flex items-center gap-4 ${appointmentType === 'presential'
                                            ? 'border-brand bg-brand/5 ring-1 ring-brand'
                                            : 'border-gray-200 hover:border-brand/50'
                                            }`}
                                    >
                                        <div className={`w-12 h-12 rounded-lg flex items-center justify-center ${appointmentType === 'presential' ? 'bg-brand text-white' : 'bg-gray-100 text-gray-500'
                                            }`}>
                                            <MapPin className="w-6 h-6" />
                                        </div>
                                        <div className="text-left">
                                            <span className={`block font-bold ${appointmentType === 'presential' ? 'text-brand' : 'text-gray-900'
                                                }`}>En présentiel</span>
                                            <span className="text-sm text-gray-500">Au bureau Handepassement</span>
                                        </div>
                                    </button>

                                    <button
                                        onClick={() => setAppointmentType('video')}
                                        className={`p-4 rounded-xl border-2 transition-all flex items-center gap-4 ${appointmentType === 'video'
                                            ? 'border-brand bg-brand/5 ring-1 ring-brand'
                                            : 'border-gray-200 hover:border-brand/50'
                                            }`}
                                    >
                                        <div className={`w-12 h-12 rounded-lg flex items-center justify-center ${appointmentType === 'video' ? 'bg-brand text-white' : 'bg-gray-100 text-gray-500'
                                            }`}>
                                            <Video className="w-6 h-6" />
                                        </div>
                                        <div className="text-left">
                                            <span className={`block font-bold ${appointmentType === 'video' ? 'text-brand' : 'text-gray-900'
                                                }`}>En visio</span>
                                            <span className="text-sm text-gray-500">Via Google Meet</span>
                                        </div>
                                    </button>
                                </div>
                            </div>

                            {/* Calendar Section */}
                            <div className="bg-white rounded-3xl shadow-xl p-8">
                                <h2 className="text-xl font-bold text-gray-900 mb-2">Sélectionner une date</h2>
                                <p className="text-sm text-gray-600 mb-6">Choisissez la date qui vous convient</p>

                                {/* Calendar */}
                                <div className="mb-8">
                                    {/* Calendar Header */}
                                    <div className="flex items-center justify-between mb-4">
                                        <button
                                            onClick={handlePrevMonth}
                                            className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
                                        >
                                            ←
                                        </button>
                                        <h3 className="text-lg font-bold text-gray-900 capitalize">
                                            {formatMonthYear(currentMonth)}
                                        </h3>
                                        <button
                                            onClick={handleNextMonth}
                                            className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
                                        >
                                            →
                                        </button>
                                    </div>

                                    {/* Calendar Grid */}
                                    <div className="border border-gray-200 rounded-lg overflow-hidden">
                                        {/* Weekday Headers */}
                                        <div className="grid grid-cols-7 bg-gray-50">
                                            {['Lu', 'Ma', 'Me', 'Je', 'Ve', 'Sa', 'Di'].map((day) => (
                                                <div key={day} className="text-center py-2 text-sm font-semibold text-gray-700">
                                                    {day}
                                                </div>
                                            ))}
                                        </div>
                                        {/* Calendar Days */}
                                        <div className="grid grid-cols-7">
                                            {emptyDays.map((i) => (
                                                <div key={`empty-${i}`} className="aspect-square border border-gray-100"></div>
                                            ))}
                                            {days.map((day) => {
                                                const date = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
                                                const isSelected = isSameDay(selectedDate, date);
                                                const isToday = isSameDay(new Date(), date);
                                                const isPast = isPastDate(date);

                                                return (
                                                    <button
                                                        key={day}
                                                        onClick={() => handleDateClick(day)}
                                                        disabled={isPast}
                                                        className={`aspect-square border border-gray-100 p-2 text-sm transition-colors relative ${isPast
                                                            ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                                                            : isSelected
                                                                ? 'bg-brand text-white font-bold'
                                                                : isToday
                                                                    ? 'bg-blue-100 text-brand font-semibold hover:bg-blue-200'
                                                                    : 'hover:bg-gray-50'
                                                            }`}
                                                    >
                                                        {day}
                                                        {isToday && !isSelected && !isPast && (
                                                            <div className="absolute bottom-1 left-1/2 transform -translate-x-1/2 w-1 h-1 bg-brand rounded-full"></div>
                                                        )}
                                                    </button>
                                                );
                                            })}
                                        </div>
                                    </div>
                                </div>

                                {/* Time Slots Section */}
                                {selectedDate && (
                                    <div>
                                        <h3 className="text-lg font-bold text-gray-900 mb-2">Créneaux disponibles</h3>
                                        <p className="text-sm text-gray-600 mb-4 capitalize">
                                            {formatSelectedDate(selectedDate)}
                                        </p>

                                        <div className="grid grid-cols-4 gap-3">
                                            {slotsLoading ? (
                                                <div className="col-span-full text-center py-2 text-gray-500">Chargement...</div>
                                            ) : availableSlots.length === 0 ? (
                                                <div className="col-span-full text-center py-2 text-gray-500 text-sm">Aucun créneau</div>
                                            ) : (
                                                availableSlots.map((time) => (
                                                    <button
                                                        key={time}
                                                        onClick={() => setSelectedTime(time)}
                                                        className={`px-4 py-3 rounded-lg border font-medium transition-colors flex items-center justify-center gap-2 ${selectedTime === time
                                                            ? 'bg-brand text-white border-brand'
                                                            : 'bg-white border-gray-300 text-gray-700 hover:border-brand hover:text-brand'
                                                            }`}
                                                    >
                                                        <Clock className="w-4 h-4" />
                                                        {time}
                                                    </button>
                                                )))}
                                        </div>
                                    </div>
                                )}
                            </div>


                            {/* Comment Section */}
                            <div className="bg-white rounded-3xl shadow-xl p-8">
                                <h2 className="text-xl font-bold text-gray-900 mb-2">Message (Optionnel)</h2>
                                <p className="text-sm text-gray-600 mb-6">Avez-vous des précisions à nous apporter ?</p>

                                <textarea
                                    value={comment}
                                    onChange={(e) => setComment(e.target.value)}
                                    placeholder="Bonjour, j'aimerais aborder..."
                                    className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-brand focus:border-transparent min-h-[120px] resize-y"
                                ></textarea>
                            </div>
                        </div>

                        {/* Right Section - Recap */}
                        <div className="lg:col-span-1">
                            <div className="bg-white rounded-3xl shadow-xl p-6 sticky top-6">
                                <h2 className="text-xl font-bold text-gray-900 mb-6">Récapitulatif</h2>

                                <div className="space-y-4 mb-6">
                                    {/* Date */}
                                    <div className="flex items-start gap-3">
                                        <div className="w-10 h-10 bg-brand/10 rounded-lg flex items-center justify-center flex-shrink-0">
                                            <CalendarIcon className="w-5 h-5 text-brand" />
                                        </div>
                                        <div>
                                            <p className="text-sm text-gray-600 mb-1">Date</p>
                                            {selectedDate ? (
                                                <p className="font-bold text-gray-900 capitalize">
                                                    {formatSelectedDate(selectedDate)}
                                                </p>
                                            ) : (
                                                <p className="text-sm text-gray-400 italic">Sélectionnez une date</p>
                                            )}
                                        </div>
                                    </div>

                                    {/* Time */}
                                    <div className="flex items-start gap-3">
                                        <div className="w-10 h-10 bg-brand/10 rounded-lg flex items-center justify-center flex-shrink-0">
                                            <Clock className="w-5 h-5 text-brand" />
                                        </div>
                                        <div>
                                            <p className="text-sm text-gray-600 mb-1">Heure</p>
                                            {selectedTime ? (
                                                <p className="font-bold text-gray-900">{selectedTime}</p>
                                            ) : (
                                                <p className="text-sm text-gray-400 italic">Sélectionnez un créneau</p>
                                            )}
                                        </div>
                                    </div>

                                    {/* Appointment Type */}
                                    <div className="flex items-start gap-3">
                                        <div className="w-10 h-10 bg-brand/10 rounded-lg flex items-center justify-center flex-shrink-0">
                                            <CheckCircle className="w-5 h-5 text-brand" />
                                        </div>
                                        <div>
                                            <p className="text-sm text-gray-600 mb-1">Type de rendez-vous</p>
                                            {appointmentType ? (
                                                <p className="font-bold text-gray-900">
                                                    {appointmentType === 'presential' ? 'En présentiel' : 'En visio'}
                                                </p>
                                            ) : (
                                                <p className="text-sm text-gray-400 italic">Sélectionnez un type</p>
                                            )}
                                        </div>
                                    </div>

                                    <button
                                        onClick={handleConfirm}
                                        disabled={!selectedDate || !selectedTime || !appointmentType || isSubmitting}
                                        className={`w-full py-3 rounded-lg font-bold transition-colors flex justify-center items-center ${selectedDate && selectedTime && appointmentType && !isSubmitting
                                            ? 'bg-brand text-white hover:bg-brand-600'
                                            : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                                            }`}
                                    >
                                        {isSubmitting ? (
                                            <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                                        ) : (
                                            'Confirmer le rendez-vous'
                                        )}
                                    </button>
                                    {error && (
                                        <p className="text-red-500 text-sm mt-2 text-center">{error}</p>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>


            {/* Confirmation Modal */}
            {
                showConfirmModal && (
                    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-6">
                        <div className="bg-white rounded-3xl p-8 max-w-md w-full relative animate-fade-in">
                            <button
                                onClick={() => setShowConfirmModal(false)}
                                className="absolute top-6 right-6 p-2 hover:bg-gray-100 rounded-lg transition-colors"
                            >
                                <X className="w-5 h-5 text-gray-500" />
                            </button>

                            <div className="text-center">
                                {/* Success Icon */}
                                <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                                    <CheckCircle className="w-8 h-8 text-green-500" />
                                </div>

                                <h2 className="text-2xl font-bold text-gray-900 mb-4">Rendez-vous confirmé !</h2>

                                <p className="text-gray-600 mb-6">
                                    Votre premier rendez-vous a été programmé avec succès pour le
                                </p>

                                <div className="bg-gray-50 rounded-xl p-6 mb-6 text-left">
                                    <div className="flex items-center gap-3 mb-3">
                                        <CalendarIcon className="w-5 h-5 text-brand" />
                                        <p className="font-bold text-gray-900 capitalize">
                                            {selectedDate && formatSelectedDate(selectedDate!)}
                                        </p>
                                    </div>
                                    <div className="flex items-center gap-3 mb-3">
                                        <Clock className="w-5 h-5 text-brand" />
                                        <p className="font-bold text-gray-900">{selectedTime}</p>
                                    </div>
                                    <div className="flex items-center gap-3">
                                        {appointmentType === 'presential' ? (
                                            <MapPin className="w-5 h-5 text-brand" />
                                        ) : (
                                            <Video className="w-5 h-5 text-brand" />
                                        )}
                                        <p className="font-bold text-gray-900">
                                            {appointmentType === 'presential' ? 'En présentiel' : 'En visio'}
                                        </p>
                                    </div>
                                    {comment && (
                                        <div className="mt-4 pt-4 border-t border-gray-200">
                                            <div className="flex gap-3">
                                                <MessageSquare className="w-5 h-5 text-brand flex-shrink-0" />
                                                <p className="text-sm text-gray-600">
                                                    "{comment}"
                                                </p>
                                            </div>
                                        </div>
                                    )}
                                </div>

                                <p className="text-sm text-gray-600 mb-8">
                                    Vous allez recevoir un email de confirmation avec tous les détails.
                                </p>

                                <button
                                    onClick={handleBackToHome}
                                    className="w-full py-3 bg-brand text-white font-bold rounded-lg hover:bg-brand-600 transition-colors"
                                >
                                    Retour à l'accueil
                                </button>
                            </div>
                        </div>
                    </div>
                )
            }

            <FooterOther />
        </>
    );
}

export default FirstRdvStep2;

import { useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Calendar, Users, BookOpen, Heart, CheckCircle } from 'lucide-react';
import heroImage from '../assets/images/image-accueil.png';
import HeaderMain from '../components/HeaderMain'
import FooterOther from '../components/FooterOther'
import Oeil from '../components/Oeil'
import { smoothScrollTo } from '../utils/smoothScroll';

function Home() {
    const services = [
        {
            icon: <Calendar className="w-6 h-6 text-brand" />,
            title: "Prise de rendez-vous",
            description: "Planifiez facilement vos rendez-vous"
        },
        {
            icon: <Users className="w-6 h-6 text-brand" />,
            title: "Accompagnement personnalisé",
            description: "Un suivi adapté à vos besoins spécifiques tout au long de votre parcours"
        },
        {
            icon: <BookOpen className="w-6 h-6 text-brand" />,
            title: "Documentation",
            description: "Informations sur les différents types de handicaps et les aménagements disponibles"
        },
        {
            icon: <Heart className="w-6 h-6 text-brand" />,
            title: "Outil de compensation",
            description: "Les outils disponibles pour compenser un handicap"
        }
    ];

    const concerns = [
        "Dyslexie", "TDAH", "Autisme",
        "Phobie scolaire", "Handicap moteur", "Dyscalculie",
        "Déficience visuelle", "Déficience auditive", "Dysgraphie"
    ];

    const location = useLocation();

    useEffect(() => {
        if (location.state && location.state.scrollTo) {
            // Petit délai pour s'assurer que le rendu est terminé
            setTimeout(() => {
                smoothScrollTo(location.state.scrollTo, 2000); // 2 secondes
            }, 100);
            // On nettoie le state pour éviter de rescroller si on refresh
            window.history.replaceState({}, document.title);
        }
    }, [location]);

    return (
        <>
            <div className="min-h-screen bg-accent-50 font-sans relative">
                {/* Hero Section */}
                <section className="bg-brand text-white pb-6 px-6 pt-1 relative overflow-hidden rounded-b-[3rem]">
                    <HeaderMain />
                    <div className="container mx-auto grid md:grid-cols-2 gap-12 items-center pb-6">
                        <div className="space-y-8 z-10">
                            <h1 className="text-4xl md:text-5xl font-bold leading-tight text-accent">
                                Des Études Supérieures Sans Obstacles. On Handiscute ?
                            </h1>
                            <Link to="/premier-rdv" className="inline-block px-8 py-3 bg-accent text-brand font-bold rounded-lg hover:bg-accent-400 transition-colors shadow-lg">
                                Prendre un premier rendez-vous
                            </Link>
                        </div>
                        <div className="relative z-10 flex justify-center md:justify-end">
                            {/* Image container with specific styling to match design */}
                            <img
                                src={heroImage}
                                alt="Étudiants diplômés"
                                className="max-w-full h-auto object-contain"
                                style={{ maxHeight: '400px' }}
                            />
                        </div>
                    </div>
                </section>

                {/* Description Section */}
                <section className="py-12 px-6">
                    <div className="container mx-auto text-center max-w-4xl">
                        <p className="text-brand text-xl leading-relaxed font-medium">
                            Accompagner les jeunes porteurs de handicap à partir du lycée et leur famille pour mieux les insérer dans l'enseignement supérieur et leur permettre la réussite de leurs études à travers de la sensibilisation et de la mise à disposition d'outils numériques
                        </p>
                    </div>
                </section>

                {/* Services Section */}
                <section className="py-16 px-6">
                    <div className="container mx-auto">
                        <div className="bg-white rounded-[3rem] p-12 shadow-xl border border-gray-100">
                            <div className="text-center mb-12">
                                <h2 className="text-3xl font-bold text-brand mb-4">Nos services</h2>
                                <p className="text-gray-500">Tous nos services sont accessibles aux adhérents de l'association</p>
                            </div>

                            <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-8">
                                {services.map((service, index) => (
                                    <div key={index} className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm hover:shadow-md transition-shadow h-full flex flex-col">
                                        <div className="w-12 h-12 bg-accent rounded-lg flex items-center justify-center mb-6">
                                            {service.icon}
                                        </div>
                                        <h3 className="text-lg font-bold text-gray-900 mb-3">{service.title}</h3>
                                        <p className="text-gray-600 text-sm leading-relaxed">{service.description}</p>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </section>

                {/* Concerns Section */}
                <section id="concerns-section" className="py-8 px-6 pb-24">
                    <div className="container mx-auto">
                        <div className="bg-white rounded-[3rem] p-12 shadow-xl border border-gray-100">
                            <div className="text-center mb-12">
                                <h2 className="text-3xl font-bold text-brand mb-4">Êtes-vous concerné ?</h2>
                                <p className="text-gray-500 max-w-2xl mx-auto text-sm">
                                    Notre association accompagne les étudiants présentant différents types de handicaps et de troubles pour garantir leur réussite dans l'enseignement supérieur.
                                </p>
                            </div>

                            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6 max-w-5xl mx-auto">
                                {concerns.map((item, index) => (
                                    <div key={index} className="flex items-center gap-4 p-4 rounded-xl border border-brand/30 bg-white hover:bg-gray-50 transition-colors">
                                        <CheckCircle className="w-6 h-6 text-accent flex-shrink-0" />
                                        <span className="font-bold text-gray-800">{item}</span>
                                    </div>
                                ))}
                            </div>

                            <div className="text-center mt-12">
                                <p className="text-xl font-bold text-gray-800">Et plein d'autres...</p>
                            </div>
                        </div>
                    </div>
                </section>

                {/* Footer CTA */}
                <section className="py-12 px-6 pb-24">
                    <div className="container mx-auto">
                        <div className="bg-brand rounded-[4rem] p-16 text-center shadow-2xl relative overflow-hidden">
                            <div className="relative z-10">
                                <h2 className="text-3xl md:text-4xl font-bold text-accent mb-4">
                                    Prenez votre premier rendez-vous !
                                </h2>
                                <p className="text-brand-100 mb-8 max-w-2xl mx-auto">
                                    Commencez dès aujourd'hui et bénéficiez d'un accompagnement sur mesure pour votre réussite
                                </p>
                                <Link to="/premier-rdv" className="inline-block px-8 py-3 bg-accent text-brand font-bold rounded-full hover:bg-accent-400 transition-colors shadow-lg">
                                    Prendre rendez-vous maintenant
                                </Link>
                            </div>
                        </div>
                    </div>
                </section>

                {/* Accessibility Button */}
                <Oeil />
            </div>
            <FooterOther />
        </>
    );
}

export default Home;

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import '../style/Inscription.css';
import { Check, ChevronLeft, ChevronRight, Eye, EyeOff, Loader2 } from 'lucide-react';
import HeaderInscription from '../components/HeaderInscription';
import { createStudent, checkStudentStatus } from '../services/airtable';

export default function Inscription() {
    const navigate = useNavigate();
    const [step, setStep] = useState(1);
    const [showPassword, setShowPassword] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [formData, setFormData] = useState({
        prenom: '',
        nom: '',
        email: '',
        phone: '',
        password: '',
        confirmPassword: '',
        university: '',
        fieldOfStudy: '',
        studyLevel: '',
        disabilityTypes: [] as string[], // Changed to array
        needsDescription: '',
        aidantFamilial: null as boolean | null,
        aidantDescription: '',
        acceptTerms: false
    });

    const validateStep = (currentStep: number) => {
        if (currentStep === 1) {
            if (!formData.prenom || !formData.nom || !formData.email || !formData.password || !formData.confirmPassword) {
                return "Veuillez remplir tous les champs obligatoires.";
            }
            if (formData.password !== formData.confirmPassword) {
                return "Les mots de passe ne correspondent pas.";
            }
            if (formData.aidantFamilial === null) {
                return "La question sur l'aidant familial est obligatoire.";
            }
        }
        if (currentStep === 2) {
            if (!formData.university || !formData.fieldOfStudy || !formData.studyLevel) {
                return "Veuillez remplir tous les champs obligatoires.";
            }
        }
        return null;
    };

    const nextStep = async () => {
        const validationError = validateStep(step);
        if (validationError) {
            setError(validationError);
            return;
        }

        if (step === 1) {
            setIsLoading(true);
            try {
                await checkStudentStatus(formData.email);
            } catch (err: any) {
                console.error(err);
                if (err.message === "ACCOUNT_EXISTS") {
                    setError("Un compte existe déjà pour cette adresse email. Veuillez vous connecter.");
                } else if (err.message === "STATUS_NOT_VALIDATION" || err.message === "EMAIL_NOT_FOUND") {
                    setError("Email non reconnu, prenez d'abord un premier rdv.");
                } else {
                    setError("Une erreur est survenue. Veuillez réessayer.");
                }
                setIsLoading(false);
                return;
            } finally {
                setIsLoading(false);
            }
        }

        setError(null);
        setStep(step + 1);
    };
    const prevStep = () => setStep(step - 1);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleCheckboxChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, checked } = e.target;
        setFormData(prev => ({ ...prev, [name]: checked }));
    };

    const handleDisabilityChange = (value: string) => {
        setFormData(prev => {
            const current = prev.disabilityTypes;
            if (current.includes(value)) {
                return { ...prev, disabilityTypes: current.filter(item => item !== value) };
            } else {
                return { ...prev, disabilityTypes: [...current, value] };
            }
        });
    };

    const handleSubmit = async () => {
        setIsLoading(true);
        setError(null);

        if (formData.disabilityTypes.length === 0) {
            setError("Veuillez sélectionner au moins un type de handicap.");
            setIsLoading(false);
            return;
        }

        try {
            await createStudent(formData as any);
            nextStep();
        } catch (err: any) {
            console.error(err);
            if (err.message === "ACCOUNT_EXISTS") {
                setError("Un compte existe déjà pour cette adresse email. Veuillez vous connecter.");
            } else if (err.message === "STATUS_NOT_VALIDATION" || err.message === "EMAIL_NOT_FOUND") {
                setError("Email non reconnu, prenez d'abord un premier rdv.");
            } else {
                setError("Une erreur est survenue lors de l'inscription. Veuillez réessayer.");
            }
        } finally {
            setIsLoading(false);
        }
    };

    const disabilityOptions = [
        "TDAH",
        "Autisme",
        "Dyslexie",
        "Dyscaculie",
        "Dysgraphie",
        "Phobie social",
        "Autre"
    ];

    return (
        <div className="page-container-background font-sans">
            <HeaderInscription />
            <div className="flex flex-col items-center w-full max-w-[600px]">

                {/* Stepper - Moved outside card */}
                {step <= 3 && (
                    <div className="stepper-container w-full mb-6">
                        <div className={`step-circle ${step >= 1 ? 'active' : ''}`}>1</div>
                        <div className={`line ${step >= 2 ? 'active' : ''}`}></div>
                        <div className={`step-circle ${step >= 2 ? 'active' : ''}`}>2</div>
                        <div className={`line ${step >= 3 ? 'active' : ''}`}></div>
                        <div className={`step-circle ${step >= 3 ? 'active' : ''}`}>3</div>
                    </div>
                )}

                <div className="white-card">
                    {/* STEP 1: Informations personnelles */}
                    {step === 1 && (
                        <div className="step-content animate-fade-in">
                            <h2 className="text-xl font-bold text-neutral-800 mb-1">Informations personnelles</h2>
                            <p className="text-sm text-neutral-500 mb-4">Étape 1 sur 3</p>

                            {error && step === 1 && (
                                <div className="mb-4 p-3 bg-red-100 text-red-700 rounded-lg text-sm">
                                    {error}
                                </div>
                            )}

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mb-3">
                                <div className="form-group">
                                    <label className="block text-xs font-medium text-neutral-700 mb-1">Prénom *</label>
                                    <input
                                        type="text"
                                        name="prenom"
                                        className="w-full px-3 py-1.5 border border-neutral-300 rounded-lg focus:ring-2 focus:ring-brand-400 focus:border-transparent outline-none transition text-sm"
                                        value={formData.prenom}
                                        onChange={handleChange}
                                        placeholder="Votre prénom"
                                    />
                                </div>
                                <div className="form-group">
                                    <label className="block text-xs font-medium text-neutral-700 mb-1">Nom *</label>
                                    <input
                                        type="text"
                                        name="nom"
                                        className="w-full px-3 py-1.5 border border-neutral-300 rounded-lg focus:ring-2 focus:ring-brand-400 focus:border-transparent outline-none transition text-sm"
                                        value={formData.nom}
                                        onChange={handleChange}
                                        placeholder="Votre nom"
                                    />
                                </div>
                            </div>

                            <div className="mb-3">
                                <label className="block text-xs font-medium text-neutral-700 mb-1">Email *</label>
                                <input
                                    type="email"
                                    name="email"
                                    className="w-full px-3 py-1.5 border border-neutral-300 rounded-lg focus:ring-2 focus:ring-brand-400 focus:border-transparent outline-none transition text-sm"
                                    value={formData.email}
                                    onChange={handleChange}
                                    placeholder="exemple@email.com"
                                />
                            </div>

                            <div className="mb-3">
                                <label className="block text-xs font-medium text-neutral-700 mb-1">Téléphone (facultatif)</label>
                                <input
                                    type="tel"
                                    name="phone"
                                    className="w-full px-3 py-1.5 border border-neutral-300 rounded-lg focus:ring-2 focus:ring-brand-400 focus:border-transparent outline-none transition text-sm"
                                    value={formData.phone}
                                    onChange={handleChange}
                                    placeholder="06 12 34 56 78"
                                />
                            </div>

                            <div className="mb-3">
                                <label className="block text-xs font-medium text-neutral-700 mb-1">Avez-vous un aidant familial ? *</label>
                                <div className="flex gap-4">
                                    <label className="flex items-center gap-2 cursor-pointer">
                                        <input
                                            type="radio"
                                            name="aidantFamilial"
                                            className="w-4 h-4 text-brand border-neutral-300 focus:ring-brand-400"
                                            checked={formData.aidantFamilial === true}
                                            onChange={() => setFormData(prev => ({ ...prev, aidantFamilial: true }))}
                                        />
                                        <span className="text-sm text-neutral-700">Oui</span>
                                    </label>
                                    <label className="flex items-center gap-2 cursor-pointer">
                                        <input
                                            type="radio"
                                            name="aidantFamilial"
                                            className="w-4 h-4 text-brand border-neutral-300 focus:ring-brand-400"
                                            checked={formData.aidantFamilial === false}
                                            onChange={() => setFormData(prev => ({ ...prev, aidantFamilial: false, aidantDescription: '' }))}
                                        />
                                        <span className="text-sm text-neutral-700">Non</span>
                                    </label>
                                </div>
                                {formData.aidantFamilial === true && (
                                    <div className="mt-2 animate-fade-in pl-1">
                                        <label className="block text-xs font-medium text-neutral-700 mb-1">Qui est votre aidant ? (facultatif)</label>
                                        <input
                                            type="text"
                                            name="aidantDescription"
                                            className="w-full px-3 py-1.5 border border-neutral-300 rounded-lg focus:ring-2 focus:ring-brand-400 focus:border-transparent outline-none transition text-sm"
                                            value={formData.aidantDescription}
                                            onChange={handleChange}
                                            placeholder="Ex: Ma mère, Mon frère..."
                                        />
                                    </div>
                                )}
                            </div>

                            <div className="mb-3 relative">
                                <label className="block text-xs font-medium text-neutral-700 mb-1">Mot de passe *</label>
                                <div className="relative">
                                    <input
                                        type={showPassword ? "text" : "password"}
                                        name="password"
                                        className="w-full px-3 py-1.5 border border-neutral-300 rounded-lg focus:ring-2 focus:ring-brand-400 focus:border-transparent outline-none transition text-sm"
                                        value={formData.password}
                                        onChange={handleChange}
                                        placeholder="Minimum 8 caractères"
                                    />
                                    <button
                                        type="button"
                                        className="absolute right-3 top-1/2 transform -translate-y-1/2 text-neutral-400 hover:text-neutral-600"
                                        onClick={() => setShowPassword(!showPassword)}
                                    >
                                        {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                                    </button>
                                </div>
                            </div>

                            <div className="mb-6">
                                <label className="block text-xs font-medium text-neutral-700 mb-1">Confirmer le mot de passe *</label>
                                <input
                                    type="password"
                                    name="confirmPassword"
                                    className="w-full px-3 py-1.5 border border-neutral-300 rounded-lg focus:ring-2 focus:ring-brand-400 focus:border-transparent outline-none transition text-sm"
                                    value={formData.confirmPassword}
                                    onChange={handleChange}
                                    placeholder="Confirmez votre mot de passe"
                                />
                            </div>

                            <div className="flex justify-end">
                                <button
                                    className={`flex items-center gap-2 bg-brand text-white px-5 py-2 rounded-lg hover:bg-brand-400 transition text-sm ${isLoading ? 'opacity-50 cursor-not-allowed' : ''}`}
                                    onClick={nextStep}
                                    disabled={isLoading}
                                >
                                    {isLoading ? (
                                        <>Vérification <Loader2 size={18} className="animate-spin" /></>
                                    ) : (
                                        <>Suivant <ChevronRight size={18} /></>
                                    )}
                                </button>
                            </div>
                        </div>
                    )}

                    {/* STEP 2: Informations académiques */}
                    {step === 2 && (
                        <div className="step-content animate-fade-in">
                            <h2 className="text-xl font-bold text-neutral-800 mb-1">Informations académiques</h2>
                            <p className="text-sm text-neutral-500 mb-4">Étape 2 sur 3</p>

                            {error && step === 2 && (
                                <div className="mb-4 p-3 bg-red-100 text-red-700 rounded-lg text-sm">
                                    {error}
                                </div>
                            )}

                            <div className="mb-3">
                                <label className="block text-xs font-medium text-neutral-700 mb-1">Université / École *</label>
                                <input
                                    type="text"
                                    name="university"
                                    className="w-full px-3 py-1.5 border border-neutral-300 rounded-lg focus:ring-2 focus:ring-brand-400 focus:border-transparent outline-none transition text-sm"
                                    value={formData.university}
                                    onChange={handleChange}
                                    placeholder="Nom de votre établissement"
                                />
                            </div>

                            <div className="mb-3">
                                <label className="block text-xs font-medium text-neutral-700 mb-1">Domaine d'études *</label>
                                <select
                                    name="fieldOfStudy"
                                    className="w-full px-3 py-1.5 border border-neutral-300 rounded-lg focus:ring-2 focus:ring-brand-400 focus:border-transparent outline-none transition bg-white text-sm"
                                    value={formData.fieldOfStudy}
                                    onChange={handleChange}
                                >
                                    <option value="">Sélectionnez un domaine</option>
                                    <option value="sciences">Sciences & Technologies</option>
                                    <option value="lettres">Lettres & Langues</option>
                                    <option value="droit">Droit & Économie</option>
                                    <option value="sante">Santé</option>
                                    <option value="arts">Arts & Design</option>
                                    <option value="autre">Autre</option>
                                </select>
                            </div>

                            <div className="mb-6">
                                <label className="block text-xs font-medium text-neutral-700 mb-1">Niveau d'études *</label>
                                <select
                                    name="studyLevel"
                                    className="w-full px-3 py-1.5 border border-neutral-300 rounded-lg focus:ring-2 focus:ring-brand-400 focus:border-transparent outline-none transition bg-white text-sm"
                                    value={formData.studyLevel}
                                    onChange={handleChange}
                                >
                                    <option value="">Sélectionnez votre niveau</option>
                                    <option value="1ère année">Licence 1</option>
                                    <option value="2ème année">Licence 2</option>
                                    <option value="3ème année">Licence 3</option>
                                    <option value="4ème année">Master 1</option>
                                    <option value="5ème année">Master 2</option>
                                    <option value="autre">Autre</option>
                                </select>
                            </div>

                            <div className="flex justify-between">
                                <button className="flex items-center gap-2 text-neutral-600 hover:text-neutral-900 px-4 py-2 transition text-sm" onClick={prevStep}>
                                    <ChevronLeft size={18} /> Précédent
                                </button>
                                <button className="flex items-center gap-2 bg-brand text-white px-5 py-2 rounded-lg hover:bg-brand-400 transition text-sm" onClick={nextStep}>
                                    Suivant <ChevronRight size={18} />
                                </button>
                            </div>
                        </div>
                    )}

                    {/* STEP 3: Besoins spécifiques */}
                    {step === 3 && (
                        <div className="step-content animate-fade-in">
                            <h2 className="text-xl font-bold text-neutral-800 mb-1">Besoins spécifiques</h2>
                            <p className="text-sm text-neutral-500 mb-4">Étape 3 sur 3</p>

                            {error && (
                                <div className="mb-4 p-3 bg-red-100 text-red-700 rounded-lg text-sm">
                                    {error}
                                </div>
                            )}

                            <div className="mb-3">
                                <label className="block text-xs font-medium text-neutral-700 mb-2">Type de handicap ou trouble (plusieurs choix possibles) *</label>
                                <div className="grid grid-cols-2 gap-2">
                                    {disabilityOptions.map((option) => (
                                        <label key={option} className={`flex items-center p-2 border rounded-lg cursor-pointer transition text-sm ${formData.disabilityTypes.includes(option) ? 'border-brand bg-brand-50 text-brand-900' : 'border-neutral-200 hover:border-brand-200'}`}>
                                            <input
                                                type="checkbox"
                                                className="w-4 h-4 text-brand border-neutral-300 rounded focus:ring-brand-400 mr-2"
                                                checked={formData.disabilityTypes.includes(option)}
                                                onChange={() => handleDisabilityChange(option)}
                                            />
                                            {option}
                                        </label>
                                    ))}
                                </div>
                            </div>

                            <div className="mb-4">
                                <label className="block text-xs font-medium text-neutral-700 mb-1">Besoins d'accompagnement (facultatif)</label>
                                <textarea
                                    name="needsDescription"
                                    rows={3}
                                    className="w-full px-3 py-1.5 border border-neutral-300 rounded-lg focus:ring-2 focus:ring-brand-400 focus:border-transparent outline-none transition resize-none text-sm"
                                    value={formData.needsDescription}
                                    onChange={handleChange}
                                    placeholder="Décrivez vos besoins particuliers..."
                                />
                            </div>

                            <div className="mb-6 flex items-start gap-2">
                                <input
                                    type="checkbox"
                                    name="acceptTerms"
                                    id="acceptTerms"
                                    className="mt-0.5 w-3.5 h-3.5 text-brand border-neutral-300 rounded focus:ring-brand-400"
                                    checked={formData.acceptTerms}
                                    onChange={handleCheckboxChange}
                                />
                                <label htmlFor="acceptTerms" className="text-xs text-neutral-600">
                                    J'accepte les conditions générales d'utilisation et la politique de confidentialité. *
                                </label>
                            </div>

                            <div className="flex justify-between">
                                <button
                                    className="flex items-center gap-2 text-neutral-600 hover:text-neutral-900 px-4 py-2 transition text-sm"
                                    onClick={prevStep}
                                    disabled={isLoading}
                                >
                                    <ChevronLeft size={18} /> Précédent
                                </button>
                                <button
                                    className={`flex items-center gap-2 bg-brand text-white px-5 py-2 rounded-lg hover:bg-brand-400 transition text-sm ${(!formData.acceptTerms || isLoading) ? 'opacity-50 cursor-not-allowed' : ''}`}
                                    onClick={handleSubmit}
                                    disabled={!formData.acceptTerms || isLoading}
                                >
                                    {isLoading ? (
                                        <>Inscription en cours <Loader2 size={18} className="animate-spin" /></>
                                    ) : (
                                        <>Terminer l'inscription <Check size={18} /></>
                                    )}
                                </button>
                            </div>
                        </div>
                    )}

                    {/* SUCCESS STATE */}
                    {step === 4 && (
                        <div className="text-center py-8 animate-fade-in">
                            <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
                                <Check size={32} className="text-green-600" />
                            </div>
                            <h2 className="text-2xl font-bold text-neutral-800 mb-3">Inscription réussie !</h2>
                            <p className="text-neutral-600 mb-6 max-w-md mx-auto text-sm">
                                Votre compte a été créé avec succès. Vous pouvez maintenant accéder à votre tableau de bord.
                            </p>
                            <button
                                onClick={() => navigate('/connexion')}
                                className="bg-brand text-white px-6 py-2.5 rounded-lg hover:bg-brand-400 transition shadow-lg hover:shadow-xl transform hover:-translate-y-1 text-sm"
                            >
                                Accéder à la page de connexion
                            </button>
                        </div>
                    )}

                    <div className="text-center mt-6 text-sm text-neutral-500">
                        Déjà inscrit ? <a href="/mon-espace" className="text-brand font-semibold hover:underline">Se connecter</a>
                    </div>

                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import HeaderClient from '../components/HeaderClient';
import FooterMain from '../components/FooterMain';
import { Calendar as CalendarIcon, Clock, ChevronLeft, ChevronRight, MapPin, Video, CheckCircle, XCircle } from 'lucide-react';
import { createRdv, getAppointmentsForStudent, IncomingRdv, cancelRdv, generateAvailableSlots } from '../services/airtable';
import { sendRdvConfirmationEmail } from '../services/email';

const PriseRDVClient: React.FC = () => {
    const navigate = useNavigate();

    // User State
    const [user, setUser] = useState<any>(null);

    // Booking State
    const [selectedDate, setSelectedDate] = useState<Date | null>(null);
    const [selectedTime, setSelectedTime] = useState<string | null>(null);
    const [appointmentType, setAppointmentType] = useState<'presential' | 'video' | null>(null);
    const [comment, setComment] = useState('');
    const [currentMonth, setCurrentMonth] = useState(new Date());

    // UI State
    const [showCancelModal, setShowCancelModal] = useState(false);
    const [showSuccessConfirmModal, setShowSuccessConfirmModal] = useState(false);
    const [appointmentToCancel, setAppointmentToCancel] = useState<string | null>(null);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [availableSlots, setAvailableSlots] = useState<string[]>([]);
    const [slotsLoading, setSlotsLoading] = useState(false);

    // Data State
    const [upcomingAppointments, setUpcomingAppointments] = useState<IncomingRdv[]>([]);

    useEffect(() => {
        const storedUser = localStorage.getItem('user');
        if (storedUser) {
            const parsedUser = JSON.parse(storedUser);
            setUser(parsedUser);
            fetchAppointments(parsedUser.id);
        } else {
            navigate('/');
        }
    }, [navigate]);

    const fetchAppointments = async (studentId: string) => {
        const apps = await getAppointmentsForStudent(studentId);
        // Filter out past appointments or just show all sorted? User said "prochain rdv", usually implies future.
        // Let's filter client side for now to be safe, although API sorts them.
        const now = new Date();
        const futureApps = apps.filter(a => new Date(a.date) >= now);
        setUpcomingAppointments(futureApps);
    };


    useEffect(() => {
        const loadSlots = async () => {
            if (selectedDate && !isPastDate(selectedDate)) {
                setSlotsLoading(true);
                const slots = await generateAvailableSlots(selectedDate);
                setAvailableSlots(slots);
                setSlotsLoading(false);
            } else {
                setAvailableSlots([]);
            }
        };
        loadSlots();
    }, [selectedDate]);

    // Calendar Helpers (Same as FirstRdvStep2)
    const getDaysInMonth = (date: Date) => {
        const year = date.getFullYear();
        const month = date.getMonth();
        const firstDay = new Date(year, month, 1);
        const lastDay = new Date(year, month + 1, 0);
        const daysInMonth = lastDay.getDate();
        const startingDayOfWeek = firstDay.getDay(); // 0 = Sunday
        return { daysInMonth, startingDayOfWeek };
    };

    const isSameDay = (date1: Date | null, date2: Date) => {
        if (!date1) return false;
        return date1.getDate() === date2.getDate() &&
            date1.getMonth() === date2.getMonth() &&
            date1.getFullYear() === date2.getFullYear();
    };

    const isPastDate = (date: Date) => {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        return date < today;
    };

    const handleDateClick = (day: number) => {
        const newDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
        if (isPastDate(newDate)) return;
        setSelectedDate(newDate);
        setSelectedTime(null);
    };

    const handlePrevMonth = () => {
        setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1));
    };

    const handleNextMonth = () => {
        setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1));
    };

    const handleConfirmBooking = async () => {
        if (selectedDate && selectedTime && appointmentType && user) {
            setIsSubmitting(true);
            setError(null);

            try {
                // Parse time
                const [hours, minutes] = selectedTime.split(':').map(Number);
                const rdvDate = new Date(selectedDate);
                rdvDate.setHours(hours, minutes);

                const lienVisio = appointmentType === 'video' ? 'Lien Meet' : '';
                const lieu = appointmentType === 'presential' ? 'Bureau Handepassement' : '';

                await createRdv({
                    date: rdvDate,
                    type: appointmentType === 'presential' ? 'Présentiel' : 'Visio',
                    status: 'Attente de Validation',
                    lieu: lieu,
                    lienVisio: lienVisio,
                    commentaires: comment,
                    studentEmail: user['Adresse mail'],
                    admin: 'Myriam'
                });

                // Send Email
                const formattedDate = rdvDate.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
                await sendRdvConfirmationEmail({
                    to_email: user['Adresse mail'],
                    to_name: user["Nom Complet"] || "Étudiant",
                    date: formattedDate,
                    time: selectedTime,
                    type: appointmentType === 'presential' ? 'Présentiel' : 'Visio',
                    location: appointmentType === 'presential' ? 'Bureau Handepassement' : 'Google Meet',
                    notes: comment
                });

                setShowSuccessConfirmModal(true);
                // Refresh list
                await fetchAppointments(user.id);

                // Reset selection
                setSelectedDate(null);
                setSelectedTime(null);
                setAppointmentType(null);
                setComment('');

            } catch (err) {
                console.error("Error booking rdv:", err);
                setError("Erreur lors de la réservation. Veuillez réessayer.");
            } finally {
                setIsSubmitting(false);
            }
        }
    };

    // Calendar Generation
    const { daysInMonth, startingDayOfWeek } = getDaysInMonth(currentMonth);
    // Adjusted empty days for Mon-Sun start if needed, but sticking to Sun=0 standard for now
    // Actually, French calendar usually starts Monday. 
    // If startingDayOfWeek is 0 (Sunday), we need 6 empty slots if we start on Monday.
    // If startingDayOfWeek is 1 (Monday), we need 0 empty slots.
    // Let's standardise on Mon-Sun grid:
    // Columns: Lu, Ma, Me, Je, Ve, Sa, Di
    // Sun=0 -> needs 6 empty. Mon=1 -> needs 0. Tue=2 -> needs 1.
    const emptySlotsCount = startingDayOfWeek === 0 ? 6 : startingDayOfWeek - 1;
    const emptySlots = Array.from({ length: emptySlotsCount }, (_, i) => i);
    const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
    const monthName = currentMonth.toLocaleDateString('fr-FR', { month: 'long', year: 'numeric' });


    return (
        <div className="min-h-screen bg-white font-sans">
            <HeaderClient />

            <main className="container mx-auto px-4 lg:px-8 py-8">
                <div className="mb-8">
                    <h1 className="text-3xl lg:text-4xl font-bold text-gray-800 mb-2">Mes rendez-vous</h1>
                    <p className="text-gray-500">Gérez vos rendez-vous et planifiez en des nouveaux</p>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    {/* Left Column - Booking */}
                    <div className="lg:col-span-2 space-y-8">

                        {/* Appointment Type Section */}
                        <div className="bg-white border border-gray-200 rounded-3xl p-6 lg:p-8 shadow-sm">
                            <h2 className="text-2xl font-semibold text-brand mb-2">Type de rendez-vous</h2>
                            <p className="text-gray-500 mb-6">Comment souhaitez-vous effectuer ce rendez-vous ?</p>

                            <div className="grid sm:grid-cols-2 gap-4">
                                <button
                                    onClick={() => setAppointmentType('presential')}
                                    className={`p-4 rounded-xl border-2 transition-all flex items-center gap-4 ${appointmentType === 'presential'
                                        ? 'border-brand bg-brand/5 ring-1 ring-brand'
                                        : 'border-gray-200 hover:border-brand/50'
                                        }`}
                                >
                                    <div className={`w-12 h-12 rounded-lg flex items-center justify-center ${appointmentType === 'presential' ? 'bg-brand text-white' : 'bg-gray-100 text-gray-500'
                                        }`}>
                                        <MapPin className="w-6 h-6" />
                                    </div>
                                    <div className="text-left">
                                        <span className={`block font-bold ${appointmentType === 'presential' ? 'text-brand' : 'text-gray-900'
                                            }`}>En présentiel</span>
                                        <span className="text-sm text-gray-500">Au bureau Handepassement</span>
                                    </div>
                                </button>

                                <button
                                    onClick={() => setAppointmentType('video')}
                                    className={`p-4 rounded-xl border-2 transition-all flex items-center gap-4 ${appointmentType === 'video'
                                        ? 'border-brand bg-brand/5 ring-1 ring-brand'
                                        : 'border-gray-200 hover:border-brand/50'
                                        }`}
                                >
                                    <div className={`w-12 h-12 rounded-lg flex items-center justify-center ${appointmentType === 'video' ? 'bg-brand text-white' : 'bg-gray-100 text-gray-500'
                                        }`}>
                                        <Video className="w-6 h-6" />
                                    </div>
                                    <div className="text-left">
                                        <span className={`block font-bold ${appointmentType === 'video' ? 'text-brand' : 'text-gray-900'
                                            }`}>En visio</span>
                                        <span className="text-sm text-gray-500">Via Google Meet</span>
                                    </div>
                                </button>
                            </div>
                        </div>

                        {/* Calendar Section */}
                        <div className="bg-white border border-gray-200 rounded-3xl p-6 lg:p-8 shadow-sm">
                            <h2 className="text-2xl font-semibold text-brand mb-1">Sélectionner une date</h2>
                            <p className="text-gray-500 mb-6">Choisissez la date qui vous convient</p>

                            <div className="border border-gray-200 rounded-xl p-4">
                                <div className="flex items-center justify-between mb-4">
                                    <h3 className="font-semibold text-lg capitalize">{monthName}</h3>
                                    <div className="flex gap-2">
                                        <button onClick={handlePrevMonth} className="p-1 hover:bg-gray-100 rounded"><ChevronLeft size={20} /></button>
                                        <button onClick={handleNextMonth} className="p-1 hover:bg-gray-100 rounded"><ChevronRight size={20} /></button>
                                    </div>
                                </div>

                                <div className="grid grid-cols-7 gap-1 text-center text-sm">
                                    {['Lu', 'Ma', 'Me', 'Je', 'Ve', 'Sa', 'Di'].map(d => (
                                        <div key={d} className="py-2 font-medium text-gray-500">{d}</div>
                                    ))}
                                    {emptySlots.map((_, i) => <div key={`empty-${i}`} />)}
                                    {days.map(day => {
                                        const date = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
                                        const isSelected = isSameDay(selectedDate, date);
                                        const isToday = isSameDay(new Date(), date);
                                        const isPast = isPastDate(date);

                                        return (
                                            <button
                                                key={day}
                                                onClick={() => handleDateClick(day)}
                                                disabled={isPast}
                                                className={`py-2 rounded-full hover:bg-blue-50 relative ${isPast
                                                    ? 'text-gray-300 cursor-not-allowed hover:bg-transparent'
                                                    : isSelected
                                                        ? 'bg-brand text-white hover:bg-brand'
                                                        : 'text-gray-700'
                                                    }`}
                                            >
                                                {day}
                                                {isToday && !isSelected && !isPast && (
                                                    <div className="absolute bottom-1 left-1/2 transform -translate-x-1/2 w-1 h-1 bg-brand rounded-full"></div>
                                                )}
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>
                        </div>

                        {/* Time Slots Section */}
                        {selectedDate && (
                            <div className="bg-white border border-gray-200 rounded-3xl p-6 lg:p-8 shadow-sm animate-in fade-in slide-in-from-top-4">
                                <h2 className="text-2xl font-semibold text-brand mb-1">Créneaux disponibles</h2>
                                <p className="text-gray-500 mb-6">
                                    {selectedDate.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}
                                </p>

                                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
                                    {slotsLoading ? (
                                        <div className="col-span-full text-center py-4 text-gray-500">Chargement des créneaux...</div>
                                    ) : availableSlots.length === 0 ? (
                                        <div className="col-span-full text-center py-4 text-gray-500">Aucun créneau disponible ce jour-là.</div>
                                    ) : (
                                        availableSlots.map((time) => (
                                            <button
                                                key={time}
                                                onClick={() => setSelectedTime(time)}
                                                className={`flex items-center justify-center gap-2 py-3 px-4 rounded-xl border transition-all ${selectedTime === time
                                                    ? 'bg-brand text-white border-brand'
                                                    : 'bg-white text-gray-700 border-gray-200 hover:border-brand hover:text-brand'
                                                    }`}
                                            >
                                                <Clock size={16} />
                                                <span className="font-semibold">{time}</span>
                                            </button>
                                        )))}
                                </div>
                            </div>
                        )}

                        {/* Comment Section */}
                        {selectedTime && (
                            <div className="bg-white border border-gray-200 rounded-3xl p-6 lg:p-8 shadow-sm animate-in fade-in slide-in-from-top-4">
                                <h2 className="text-2xl font-semibold text-brand mb-2">Message (Optionnel)</h2>
                                <p className="text-gray-500 mb-6">Avez-vous des précisions à nous apporter ?</p>
                                <textarea
                                    value={comment}
                                    onChange={(e) => setComment(e.target.value)}
                                    placeholder="Bonjour, j'aimerais aborder..."
                                    className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-brand focus:border-transparent min-h-[100px] resize-y"
                                ></textarea>
                            </div>
                        )}
                    </div>

                    {/* Right Column - Summary & Existing RDV */}
                    <div className="space-y-8 sticky top-4 h-fit max-h-[calc(100vh-2rem)] overflow-y-auto no-scrollbar">
                        {/* Recap Section */}
                        <div className="bg-white border border-gray-200 rounded-3xl p-6 lg:p-8 shadow-sm">
                            <h2 className="text-2xl font-semibold text-brand mb-6">Récapitulatif</h2>

                            <div className="flex items-start gap-4 mb-6">
                                <div className="p-2 bg-blue-50 rounded-lg text-brand">
                                    <CalendarIcon size={24} />
                                </div>
                                <div>
                                    <p className="text-sm text-gray-500 font-medium uppercase tracking-wide">Date</p>
                                    <p className="font-bold text-gray-800 text-lg capitalize">
                                        {selectedDate ? selectedDate.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }) : '-'}
                                    </p>
                                    {selectedTime && (
                                        <p className="font-bold text-gray-800 text-lg mt-1">
                                            à {selectedTime}
                                        </p>
                                    )}
                                </div>
                            </div>

                            <div className="flex items-start gap-4 mb-8">
                                <div className="p-2 bg-blue-50 rounded-lg text-brand">
                                    {appointmentType === 'video' ? <Video size={24} /> : <MapPin size={24} />}
                                </div>
                                <div>
                                    <p className="text-sm text-gray-500 font-medium uppercase tracking-wide">Type</p>
                                    <p className="font-bold text-gray-800 text-lg">
                                        {appointmentType === 'presential' ? 'En présentiel' : appointmentType === 'video' ? 'En visio' : '-'}
                                    </p>
                                </div>
                            </div>

                            <button
                                onClick={handleConfirmBooking}
                                disabled={!selectedDate || !selectedTime || !appointmentType || isSubmitting}
                                className={`w-full py-4 rounded-xl font-bold text-white transition-colors flex justify-center items-center ${selectedDate && selectedTime && appointmentType && !isSubmitting ? 'bg-brand hover:bg-brand-600' : 'bg-gray-300 cursor-not-allowed'
                                    }`}
                            >
                                {isSubmitting ? (
                                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                ) : (
                                    'Confirmer le rendez-vous'
                                )}
                            </button>
                            {error && <p className="text-red-500 text-sm mt-4 text-center">{error}</p>}
                        </div>

                        {/* Upcoming Appointments */}
                        <div className="bg-white border border-gray-200 rounded-3xl p-6 lg:p-8 shadow-sm h-fit">
                            <h2 className="text-2xl font-semibold text-brand mb-1">Prochains rdv</h2>
                            <p className="text-gray-500 mb-6">
                                {upcomingAppointments.length} rendez-vous à venir
                            </p>

                            <div className="space-y-4">
                                {upcomingAppointments.length === 0 ? (
                                    <p className="text-gray-400 italic text-center py-4">Aucun rendez-vous à venir</p>
                                ) : (
                                    upcomingAppointments.map((apt) => (
                                        <div key={apt.id} className="border border-gray-100 rounded-2xl p-4 bg-gray-50/50">
                                            <h3 className="font-bold text-gray-800 mb-2">Rendez-vous {apt.type}</h3>

                                            <div className="space-y-2 mb-4">
                                                <div className="flex items-center gap-3 text-gray-600 text-sm">
                                                    <CalendarIcon size={16} />
                                                    {/* Date string from Airtable is ISO. Let's format nicely if possible, or just display */}
                                                    <span>{new Date(apt.date).toLocaleDateString()}</span>
                                                </div>
                                                <div className="flex items-center gap-3 text-gray-600 text-sm">
                                                    <Clock size={16} />
                                                    <span>
                                                        {(() => {
                                                            const d = new Date(apt.date);
                                                            // Use UTC to display exactly what is in Airtable (11:30Z -> 11:30)
                                                            return `${d.getUTCHours().toString().padStart(2, '0')}:${d.getUTCMinutes().toString().padStart(2, '0')}`;
                                                        })()}
                                                    </span>
                                                </div>

                                            </div>

                                            <div className="flex items-center justify-between pt-2">
                                                <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider ${apt.status === 'Réalisé' ? 'bg-green-100 text-green-700' :
                                                    apt.status === 'Annulé' ? 'bg-red-100 text-red-700' :
                                                        'bg-blue-100 text-blue-700'
                                                    }`}>
                                                    {apt.status}
                                                </span>
                                                {apt.status !== 'Annulé' && apt.status !== 'Réalisé' && (
                                                    <button
                                                        onClick={() => {
                                                            setAppointmentToCancel(apt.id);
                                                            setShowCancelModal(true);
                                                        }}
                                                        className="text-red-500 hover:text-red-700 text-sm font-semibold flex items-center gap-1 transition-colors"
                                                    >
                                                        <XCircle size={16} />
                                                        Annuler
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </main>

            {/* Success Modal */}
            {showSuccessConfirmModal && (
                <div className="fixed inset-0 bg-black/30 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-3xl p-8 max-w-md w-full shadow-2xl flex flex-col items-center text-center animate-in fade-in zoom-in duration-200">
                        <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center text-green-600 mb-4">
                            <CheckCircle size={32} strokeWidth={3} />
                        </div>
                        <h3 className="text-xl font-bold text-brand mb-2">Rendez-vous confirmé !</h3>
                        <p className="text-gray-600 mb-6">
                            Votre rendez-vous a été programmé avec succès.<br />
                            Vous recevrez un email de confirmation prochainement.
                        </p>
                        <button
                            onClick={() => setShowSuccessConfirmModal(false)}
                            className="w-full py-3 rounded-xl bg-brand text-white font-bold hover:bg-brand-dark transition-colors"
                        >
                            Fermer
                        </button>
                    </div>
                </div>
            )}

            {/* Cancel Confirmation Modal */}
            {showCancelModal && (
                <div className="fixed inset-0 bg-black/30 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-3xl p-8 max-w-md w-full shadow-2xl animate-in fade-in zoom-in duration-200">
                        <h3 className="text-xl font-bold text-gray-900 mb-2">Annuler le rendez-vous ?</h3>
                        <p className="text-gray-600 mb-6">
                            Êtes-vous sûr de vouloir annuler ce rendez-vous ?<br />
                            Cette action est irréversible.
                        </p>
                        <div className="flex gap-3">
                            <button
                                onClick={() => setShowCancelModal(false)}
                                className="flex-1 py-3 rounded-xl bg-gray-100 text-gray-700 font-bold hover:bg-gray-200 transition-colors"
                            >
                                Retour
                            </button>
                            <button
                                onClick={async () => {
                                    if (appointmentToCancel) {
                                        setIsSubmitting(true);
                                        try {
                                            await cancelRdv(appointmentToCancel);
                                            await fetchAppointments(user.id); // Refresh
                                            setShowCancelModal(false);
                                            setAppointmentToCancel(null);
                                        } catch (e) {
                                            console.error(e);
                                            alert("Erreur lors de l'annulation");
                                        } finally {
                                            setIsSubmitting(false);
                                        }
                                    }
                                }}
                                disabled={isSubmitting}
                                className="flex-1 py-3 rounded-xl bg-red-100 text-red-600 font-bold hover:bg-red-200 transition-colors flex justify-center items-center"
                            >
                                {isSubmitting ? (
                                    <div className="w-5 h-5 border-2 border-red-600/30 border-t-red-600 rounded-full animate-spin" />
                                ) : (
                                    'Confirmer l\'annulation'
                                )}
                            </button>
                        </div>
                    </div>
                </div>
            )}
            <FooterMain />
        </div>
    );
};

export default PriseRDVClient;

import React, { useState, useEffect } from 'react';
import { getAllAppointments, IncomingRdv, updateRdv, createAvailability } from '../services/airtable';
import { sendRdvUpdateEmail } from '../services/email';
import { Calendar as CalendarIcon, Clock, Plus, Edit, X, CheckCircle } from 'lucide-react';
import HeaderAdmin from '../components/HeaderAdmin';
import FooterMain from '../components/FooterMain';
import Oeil from '../components/Oeil';

const RDVAdmin: React.FC = () => {
    const [activeTab, setActiveTab] = useState<'upcoming' | 'past'>('upcoming');
    const [isNewAppointmentModalOpen, setIsNewAppointmentModalOpen] = useState(false);
    const [isEditAppointmentModalOpen, setIsEditAppointmentModalOpen] = useState(false);
    const [isConfirmationModalOpen, setIsConfirmationModalOpen] = useState(false);
    const [isAvailabilityModalOpen, setIsAvailabilityModalOpen] = useState(false);
    const [selectedDate, setSelectedDate] = useState<Date>(new Date());
    const [filterDate, setFilterDate] = useState<Date | null>(null);
    const [appointmentToEdit, setAppointmentToEdit] = useState<IncomingRdv | null>(null);


    const [appointments, setAppointments] = useState<IncomingRdv[]>([]);

    useEffect(() => {
        const fetchAppointments = async () => {
            try {
                const data = await getAllAppointments();
                setAppointments(data);
            } catch (error) {
                console.error("Failed to fetch appointments", error);
            }
        };

        fetchAppointments();
    }, []);

    const now = new Date();

    // Filter by date if selected
    const filteredAppointments = filterDate
        ? appointments.filter(apt => {
            const aptDate = new Date(apt.date);
            return aptDate.getDate() === filterDate.getDate() &&
                aptDate.getMonth() === filterDate.getMonth() &&
                aptDate.getFullYear() === filterDate.getFullYear();
        })
        : appointments;

    // Split and Sort
    // Upcoming: Closest to furthest (Ascending)
    const upcomingAppointments = filteredAppointments
        .filter(apt => new Date(apt.date) >= now)
        .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    // Past: Closest to furthest (Descending from now)
    const pastAppointments = filteredAppointments
        .filter(apt => new Date(apt.date) < now)
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    const upcomingCount = upcomingAppointments.length;
    const pastCount = pastAppointments.length;

    const [newAppointment, setNewAppointment] = useState({
        student: '',
        type: '',
        date: '',
        time: ''
    });

    const [editAppointment, setEditAppointment] = useState({
        student: '',
        type: '',
        date: '',
        time: '',
        status: ''
    });

    const [confirmedAppointment] = useState({
        date: '',
        time: ''
    });

    const [availabilityForm, setAvailabilityForm] = useState({
        date: new Date().toISOString().split('T')[0],
        startTime: '09:00',
        endTime: '17:00'
    });

    // Mock handlers to satisfy lints
    const handleCreateAppointment = () => { console.log('Create not implemented'); setIsNewAppointmentModalOpen(false); };

    const handleEditAppointment = async () => {
        if (!appointmentToEdit) return;

        try {
            let newDate: Date | undefined = undefined;
            if (editAppointment.date && editAppointment.time) {
                newDate = new Date(`${editAppointment.date}T${editAppointment.time}`);
            }

            const updatedFields = {
                type: editAppointment.type as any,
                date: newDate,
                status: editAppointment.status as any
            };

            const updatedData = await updateRdv(appointmentToEdit.id, updatedFields);

            // Check if status changed and send email
            if (appointmentToEdit.status !== editAppointment.status) {
                console.log(`Status changed for appointment ${appointmentToEdit.id}. Sending email...`);

                const rdvDate = newDate || new Date(appointmentToEdit.date);
                const formattedDate = rdvDate.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
                const formattedTime = rdvDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

                await sendRdvUpdateEmail({
                    to_email: updatedData.studentEmail,
                    to_name: updatedData.studentName,
                    date: formattedDate,
                    time: formattedTime,
                    type: editAppointment.type,
                    location: "Voir détails",
                    new_status: editAppointment.status,
                    notes: "Le statut de votre rendez-vous a été mis à jour."
                });
            }

            setIsEditAppointmentModalOpen(false);
            setAppointmentToEdit(null);

            // Refresh appointments list
            const data = await getAllAppointments();
            setAppointments(data);

        } catch (error) {
            console.error("Failed to update appointment", error);
            alert("Erreur lors de la mise à jour du rendez-vous.");
        }
    };

    const handleCreateAvailability = async () => {
        try {
            await createAvailability({
                date: availabilityForm.date,
                startTime: availabilityForm.startTime,
                endTime: availabilityForm.endTime
            });
            setIsAvailabilityModalOpen(false);
            alert("Disponibilité ajoutée avec succès !");
        } catch (error) {
            console.error("Failed to create availability", error);
            alert("Erreur lors de l'ajout de la disponibilité.");
        }
    };

    const openEditModal = (apt: IncomingRdv) => {
        setAppointmentToEdit(apt);
        const dateObj = new Date(apt.date);
        const timeString = dateObj.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit', hour12: false });
        setEditAppointment({
            student: apt.studentName,
            type: apt.type,
            date: dateObj.toISOString().split('T')[0],
            time: timeString,
            status: apt.status
        });
        setIsEditAppointmentModalOpen(true);
    };

    // Simple calendar component
    const renderCalendar = () => {
        const currentMonth = selectedDate.getMonth();
        const currentYear = selectedDate.getFullYear();
        const firstDay = new Date(currentYear, currentMonth, 1).getDay();
        const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

        const monthNames = ['Janvier', 'Février', 'Mars', 'Avril', 'Mai', 'Juin',
            'Juillet', 'Août', 'Septembre', 'Octobre', 'Novembre', 'Décembre'];
        const dayNames = ['Dim', 'Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam'];

        const days = [];
        for (let i = 0; i < firstDay; i++) {
            days.push(<div key={`empty-${i}`} className="p-2"></div>);
        }
        for (let day = 1; day <= daysInMonth; day++) {
            const date = new Date(currentYear, currentMonth, day);
            const isToday = day === new Date().getDate() &&
                currentMonth === new Date().getMonth() &&
                currentYear === new Date().getFullYear();

            const isSelected = filterDate &&
                day === filterDate.getDate() &&
                currentMonth === filterDate.getMonth() &&
                currentYear === filterDate.getFullYear();

            const hasAppointment = appointments.some(apt => {
                const aptDate = new Date(apt.date);
                return aptDate.getDate() === day &&
                    aptDate.getMonth() === currentMonth &&
                    aptDate.getFullYear() === currentYear;
            });

            days.push(
                <div
                    key={day}
                    onClick={() => {
                        if (isSelected) {
                            setFilterDate(null);
                        } else {
                            setFilterDate(date);
                        }
                    }}
                    className={`p-2 text-center text-sm cursor-pointer rounded-lg transition-colors relative
                        ${isSelected ? 'bg-brand text-white font-bold' :
                            isToday ? 'bg-blue-100 text-brand font-bold' :
                                'hover:bg-gray-100 text-gray-700'
                        }
`}
                >
                    {day}
                    {hasAppointment && !isSelected && (
                        <div className="absolute bottom-1 left-1/2 transform -translate-x-1/2 w-1 h-1 bg-brand rounded-full"></div>
                    )}
                </div>
            );
        }

        return (
            <div className="bg-white rounded-xl border border-gray-200 p-6">
                <h3 className="text-lg font-bold text-gray-900 mb-4">Calendrier</h3>
                <p className="text-sm text-gray-500 mb-4">Sélectionner une date</p>

                <div className="mb-4 flex items-center justify-between">
                    <button
                        onClick={() => setSelectedDate(new Date(currentYear, currentMonth - 1, 1))}
                        className="p-1 hover:bg-gray-100 rounded"
                    >
                        ❮
                    </button>
                    <span className="font-semibold text-gray-900">
                        {monthNames[currentMonth]} {currentYear}
                    </span>
                    <button
                        onClick={() => setSelectedDate(new Date(currentYear, currentMonth + 1, 1))}
                        className="p-1 hover:bg-gray-100 rounded"
                    >
                        ❯
                    </button>
                </div>

                <div className="grid grid-cols-7 gap-1 mb-2">
                    {dayNames.map(day => (
                        <div key={day} className="text-center text-xs font-semibold text-gray-500 p-2">
                            {day}
                        </div>
                    ))}
                </div>

                <div className="grid grid-cols-7 gap-1">
                    {days}
                </div>

                <div className="mt-6 pt-6 border-t border-gray-100">
                    <button
                        onClick={() => setIsAvailabilityModalOpen(true)}
                        className="w-full py-2 bg-slate-800 text-white font-semibold rounded-lg hover:bg-slate-700 transition-colors flex items-center justify-center gap-2 text-sm"
                    >
                        <Plus className="w-4 h-4" />
                        Ajouter mes disponibilités
                    </button>
                </div>
            </div>
        );
    };

    return (
        <>
            <div className="min-h-screen bg-gray-50 py-8 px-6">
                <HeaderAdmin />
                <div className="container mx-auto max-w-7xl">
                    {/* Header */}
                    <div className="mb-8 flex items-center justify-between">
                        <div>
                            <h1 className="text-3xl font-bold text-gray-900 mb-2">
                                Gestion des rendez-vous
                            </h1>
                            <p className="text-gray-500">
                                Planifier et gérer tous les rendez-vous
                            </p>
                        </div>
                    </div>

                    {/* Main Grid */}
                    <div className="grid lg:grid-cols-3 gap-8">
                        {/* Left Column - Calendar */}
                        <div className="lg:col-span-1">
                            {renderCalendar()}
                        </div>

                        {/* Right Column - Appointments */}
                        <div className="lg:col-span-2">
                            <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
                                {/* Tabs */}
                                <div className="flex border-b border-gray-200">
                                    <button
                                        onClick={() => setActiveTab('upcoming')}
                                        className={`flex-1 px-6 py-4 text-sm font-semibold transition-colors ${activeTab === 'upcoming'
                                            ? 'text-brand border-b-2 border-brand'
                                            : 'text-gray-500 hover:text-gray-700'
                                            } `}
                                    >
                                        À venir ({upcomingCount})
                                    </button>
                                    <button
                                        onClick={() => setActiveTab('past')}
                                        className={`flex-1 px-6 py-4 text-sm font-semibold transition-colors ${activeTab === 'past'
                                            ? 'text-brand border-b-2 border-brand'
                                            : 'text-gray-500 hover:text-gray-700'
                                            } `}
                                    >
                                        Passées ({pastCount})
                                    </button>
                                </div>

                                {/* Content */}
                                <div className="p-6">
                                    <div className="mb-4">
                                        <h2 className="text-xl font-bold text-gray-900">Rendez-vous à venir</h2>
                                        <p className="text-sm text-gray-500">Rendez-vous confirmés et en attente</p>
                                    </div>

                                    <div className="space-y-4">
                                        {activeTab === 'upcoming' && upcomingAppointments.map((apt) => (
                                            <div key={apt.id} className="border border-gray-200 rounded-lg p-6">
                                                <div className="flex items-start justify-between mb-4">
                                                    <div className="flex-1">
                                                        <div className="flex items-center justify-between mb-2">
                                                            <h3 className="text-lg font-bold text-gray-900">{apt.studentName}</h3>
                                                            <span
                                                                className={`px-3 py-1 rounded-full text-xs font-semibold ${['Validé', 'Confirmé', 'Réalisé'].includes(apt.status) ? 'bg-green-100 text-green-700' :
                                                                    ['Annulé', 'Refusé'].includes(apt.status) ? 'bg-red-100 text-red-700' :
                                                                        ['Reporté'].includes(apt.status) ? 'bg-orange-100 text-orange-700' :
                                                                            'bg-yellow-100 text-yellow-700'
                                                                    }`}
                                                            >
                                                                {apt.status}
                                                            </span>
                                                        </div>
                                                        <p className="text-sm text-gray-600 mb-3">{apt.type}</p>
                                                        <div className="flex items-center gap-4 text-sm text-gray-500">
                                                            <div className="flex items-center gap-1">
                                                                <CalendarIcon className="w-4 h-4" />
                                                                {new Date(apt.date).toLocaleDateString()}
                                                            </div>
                                                            <div className="flex items-center gap-1">
                                                                <Clock className="w-4 h-4" />
                                                                {new Date(apt.date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                                <div className="flex items-center gap-3 pt-4 border-t border-gray-100">
                                                    <button
                                                        onClick={() => openEditModal(apt)}
                                                        className="inline-flex items-center gap-1 text-gray-700 hover:text-brand font-medium text-sm transition-colors"
                                                    >
                                                        <Edit className="w-4 h-4" />
                                                        Modifier
                                                    </button>
                                                </div>
                                            </div>
                                        ))}

                                        {activeTab === 'past' && pastAppointments.map((apt) => (
                                            <div key={apt.id} className="border border-gray-200 rounded-lg p-6 bg-gray-50">
                                                <div className="flex items-start justify-between mb-4">
                                                    <div className="flex-1">
                                                        <h3 className="text-lg font-bold text-gray-900 mb-2">{apt.studentName}</h3>
                                                        <p className="text-sm text-gray-600 mb-3">{apt.type}</p>
                                                        <div className="flex items-center gap-4 text-sm text-gray-500">
                                                            <div className="flex items-center gap-1">
                                                                <CalendarIcon className="w-4 h-4" />
                                                                {new Date(apt.date).toLocaleDateString()}
                                                            </div>
                                                            <div className="flex items-center gap-1">
                                                                <Clock className="w-4 h-4" />
                                                                {new Date(apt.date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Accessibility Button */}
                <Oeil />
            </div>

            {/* New Appointment Modal */}
            {isNewAppointmentModalOpen && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full">
                        <div className="bg-white border-b border-gray-200 px-8 py-6 flex items-center justify-between rounded-t-2xl">
                            <div>
                                <h2 className="text-2xl font-bold text-gray-900">Nouveau rendez-vous</h2>
                                <p className="text-sm text-gray-500 mt-1">Planifier un rendez-vous pour un étudiant</p>
                            </div>
                            <button
                                onClick={() => setIsNewAppointmentModalOpen(false)}
                                className="text-gray-400 hover:text-gray-600 transition-colors"
                            >
                                <X className="w-6 h-6" />
                            </button>
                        </div>

                        <div className="p-8">
                            <div className="space-y-5">
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                                        Étudiant
                                    </label>
                                    <select
                                        value={newAppointment.student}
                                        onChange={(e) => setNewAppointment({ ...newAppointment, student: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent"
                                    >
                                        <option value="">Sélectionner un étudiant</option>
                                        <option value="Marie Dubois">Marie Dubois</option>
                                        <option value="Pierre Martin">Pierre Martin</option>
                                        <option value="Sophie Laurent">Sophie Laurent</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                                        Type de rendez-vous
                                    </label>
                                    <input
                                        type="text"
                                        placeholder="Ex: Suivi pédagogique, Orientation..."
                                        value={newAppointment.type}
                                        onChange={(e) => setNewAppointment({ ...newAppointment, type: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent"
                                    />
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-semibold text-gray-700 mb-2">
                                            Date
                                        </label>
                                        <input
                                            type="date"
                                            value={newAppointment.date}
                                            onChange={(e) => setNewAppointment({ ...newAppointment, date: e.target.value })}
                                            className="w-full px-4 py-3 bg-gray-50 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-semibold text-gray-700 mb-2">
                                            Heure
                                        </label>
                                        <input
                                            type="time"
                                            value={newAppointment.time}
                                            onChange={(e) => setNewAppointment({ ...newAppointment, time: e.target.value })}
                                            className="w-full px-4 py-3 bg-gray-50 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand focus:border-transparent"
                                        />
                                    </div>
                                </div>
                            </div>

                            <div className="flex gap-3 mt-6">
                                <button
                                    onClick={() => {
                                        setNewAppointment({
                                            student: '',
                                            type: '',
                                            date: '',
                                            time: ''
                                        });
                                        setIsNewAppointmentModalOpen(false);
                                    }}
                                    className="flex-1 py-3 border border-gray-300 text-gray-700 font-semibold rounded-lg hover:bg-gray-50 transition-colors"
                                >
                                    Annuler
                                </button>
